	\end{cases}
\end{align}

post_theorem_intro_text:
\begin{remark}
	The stabilizing role of background magnetic fields in the MHD equations has been well studied in previous works \cite{lin-2014-GlobalSmallSolutions,full-not-bardos}. Our analysis reveals that despite the stabilization effect of the  background magnetic fields, the data-to-solution map for the resistive MHD equations \eqref{mhd} maintains its non-uniform continuity property for arbitrary non-zero constant fields ${\bf B_0}\neq {\bf 0}$.
\end{remark}

To simplify the notations, we write the perturbed system as follows
\begin{align}\label{mhd-B}
	\begin{cases}
		\partial_t u+u \cdot \nabla u+\nabla p=b\cdot \nabla b+{\bf B_0}\cdot\nabla b,\\[1mm]
		\partial_t b-\Delta b+u\cdot \nabla b=b\cdot\nabla u+{\bf B_0}\cdot\nabla u,  \\[1mm]
		\text{div}\, u=\text{div}\, b=0, \\[1mm]
		u(x, 0)=u_0(x),\,\, b(x, 0)=b_0(x),
	\end{cases}
\end{align}
where we denote $b - {\bf B_0}$ by $b$ for convenience.

We now explain the main ideas of the proof of  Theorem \ref{thm}. It is recalled that  Himonas and Misiołek  \cite{nonuniform-2010-cmp-himonas} introduced a frequency decomposition to construct  approximate solutions of the two-dimensional incompressible Euler equations. Denote
 \begin{align}\label{1.1}
	u^{\pm1,\lambda}(x,t)=u^{l,\pm1,\lambda}(x,t)+u^{h,\pm1,\lambda}(x,t),
\end{align}
where
\begin{itemize}
	\item[(i)] the low-frequency components $u^{l,\pm1,\lambda}$ are  obtained by solving the Euler equations with  low-frequency initial data;
	\item[(ii)] the high-frequency components $u^{h,\pm1,\lambda}$ are explicitly constructed by using  oscillatory profiles, with frequency parameter $\lambda$ controlling the spatial concentration,
	\begin{align}\label{1.2}
		u^{h,\pm1,\lambda}(x,t)=\nabla^\perp \left(\lambda^{-\delta-s-1}\phi\left(\dfrac{x_1}{\lambda^\delta}\right)\phi\left(\dfrac{x_2}{\lambda^\delta}\right)\sin (\lambda x_2\mp t)\right).
	\end{align}
Here, $\lambda>0, \max\{1-s,0\}<\delta < 1$ and $\phi\in C_c^\infty(\mathbb{R})$ with $\text{supp}\,\phi \subset [-2,2]$ and $\phi(x) \equiv 1$ on $|x| < 1$.
\end{itemize}

It is required to modify the construction of the approximate solutions in the presence of the magnetic field. To the resistive MHD equations, due to the diffusive nature of the magnetic field evolution (versus the purely transport equations of the Euler equations ), we restrict high-frequency perturbations to the velocity field alone and  maintain low-frequency components for the magnetic field. More precisely, in the case $\mathbf{B_0} = \mathbf{0}$ (no background magnetic field) and $d=2$,  we set
\begin{itemize}
	\item the low-frequency pairs $(u^{l,\pm1,\lambda}, b^{\pm1,\lambda})$ by solving the resistive MHD equations \eqref{mhd} (equivalently, system \eqref{mhd-B} with $\mathbf{B_0} = \mathbf{0}$) with low-frequency initial data;
	\item the high-frequency velocity components $u^{h,\pm1,\lambda}$ by retain their profiles as in  \eqref{1.2}.
\end{itemize}

In the three-dimensional case $(d = 3)$, we modify  the high-frequency velocity components as
	\begin{align}\label{1.3}
	u^{h,\pm1,\lambda}(x,t)=\begin{pmatrix}
		\partial_{x_1}\\[1mm]
		-\partial_{x_2}\\[1mm]
		0
	\end{pmatrix} \left(\lambda^{-\delta-s-1}\phi\left(\dfrac{x_1}{\lambda^\delta}\right)\phi\left(\dfrac{x_2}{\lambda^\delta}\right)\sin (\lambda x_2\mp t)\phi(x_3)\right).
\end{align}

The error terms induced by the  high-frequency  $u^{h,\pm1,\lambda}$   can be written as
\begin{align}\label{1.4}
	E^{\pm1,\lambda}&=\partial_t u^{h,\pm1,\lambda}+u^{l,\pm1,\lambda}\cdot\nabla u^{h,\pm1,\lambda}+u^{h,\pm1,\lambda}\cdot\nabla u^{h,\pm1,\lambda}+u^{h,\pm1,\lambda}\cdot\nabla u^{l,\pm1,\lambda},\\\label{1.5}
	F^{\pm1,\lambda}&=u^{h,\pm1,\lambda}\cdot\nabla b^{\pm1,\lambda}-b^{\pm1,\lambda}\cdot\nabla u^{h,\pm1,\lambda},
\end{align}
respectively.

Direct estimation of \eqref{1.5} will lead to uncontrolled error terms. Our alternative approach consists of three key steps:
\begin{enumerate}
	\item {\bf Divergence reformulation:} We express $F^{\pm1,\lambda} =\text{div}\,\, \tilde{F}^{\pm1,\lambda}$ and establish estimates for $\tilde{F}^{\pm1,\lambda}$;
	\item {\bf Integration by parts:} In $L^2$ inner product computations, we transfer the divergence operator to $b^{\pm1,\lambda}$ via integration by parts;
	\item {\bf Diffusion cancellation:} The resulting terms are precisely canceled by exploiting the magnetic diffusion term $\Delta b^{\pm1,\lambda}$.
\end{enumerate}

For non-zero background fields $\mathbf{B_0}=(B_1,B_2) \neq \mathbf{0}$, we introduce the coordinate transformation
\begin{align*}
	x_2 \mapsto B_1x_2 - B_2x_1,
\end{align*}
which maintains all norm estimates while achieving exact cancellation of the dominant high-frequency linear term $\mathbf{B_0} \cdot \nabla u^{h,\pm 1,\lambda}$ appearing in the error analysis of $F^{\pm1,\lambda}$.

A key observation is that the directional derivative exhibits a better decay:
\begin{align*}
	\left\|\mathbf{B_0} \cdot \nabla u^{h,\pm 1,\lambda}\right\|_{L^2}\leq C\lambda^{-s-\delta} \ll \left\|u^{h,\pm 1,\lambda}\right\|_{L^2}\leq C\lambda^{-s}, \text{~for~}\lambda \to \infty,
\end{align*}
where $\delta>0$ represent the improved decay rate.

	 The paper is organized as follows. section \ref{sec:2} is the preliminary analytical framework, in which subsection \ref{sec:2.1} is about key Lemmas and subsection \ref{sec:2.2} is on the local well-posedness theory. The core  strategy of the proof is implemented in section \ref{sec:3} (zero background field case, $\mathbf{B_0} = \mathbf{0}$) and section  \ref{sec:4} (non-zero background field case, $\mathbf{B_0} \neq \mathbf{0}$), following the approach as follows: construction of approximate solutions in subsections \ref{sec:3.1} and \ref{sec:4.1}, precise estimation of approximation errors in subsections \ref{sec:3.2} and \ref{sec:4.2}, rigorous construction of exact solutions in subsections \ref{sec:3.3} and \ref{sec:4.3}, finishing the proof of Theorem in the case $\mathbf{B_0} = \mathbf{0}$ and $\mathbf{B_0} \neq \mathbf{0}$ in subsections \ref{sec:3.4} and \ref{sec:4.4}, respectively.

{\bf Notations:}
\begin{enumerate}
\item {\bf Function Spaces:} Throughout this work, let $X$ denote a Banach space equipped with norm $\|\cdot\|_X$. Since all function spaces considered here are defined on $\mathbb{R}^d$ for $d = 2,3$, we will suppress the domain $\mathbb{R}^d$ in our notation unless otherwise specified.
	\item {\bf Differential Operators:} For $x \in \mathbb{R}^2$, we define the perpendicular gradient operator as $\nabla^\perp := (\partial_{x_2}, -\partial_{x_1})$.
	\item {\bf Joint Norms:} Given functions $f, g \in X(\mathbb{R}^d)$, we define their joint norm by
\begin{align*}
	\|f(\cdot),g(\cdot)\|_{X(\mathbb{R}^d)}=	\|f(\cdot)\|_{X(\mathbb{R}^d)}+	\|g(\cdot)\|_{X(\mathbb{R}^d)}
\end{align*}
adopting this concise notation for simplicity.
\end{enumerate}

