ref_dict.thm:main:
\begin{thm}
  \label{thm:main}
  Let $\dim X =2$. There is a unique $\T\in\PD{X}{\R^2}$ such that $\T(B_X)\supset B_{\R^2}$ and
  \begin{equation}
    \label{eq:tm=d2}
    \|\T\| = d_2(X).
  \end{equation}
  $\T$ is characterised by the following property:

  There are $x_i\in S_X$, $i=1,2$, with $x_1\neq \pm x_2$, and $y_i\in S_X$, $i=1,2$, with $y_1\neq \pm y_2$, such that:
  \begin{equation}
    \label{eq:x-distance}
    |\T x_i| = \|\T\|,\quad i=1,2,
  \end{equation}
  \begin{equation}
    \label{eq:y-contact}
    |\T y_i| = 1,\quad i=1,2,
  \end{equation}
  \begin{equation}
    \label{eq:x-between-y}
    y_1\in\cone \{x_1,x_2\},\quad y_2\in\cone\{-x_1,x_2\}.
  \end{equation}
\end{thm}

