        \gamma \in [1, 8/3) & \text{if } N=3.
    \end{cases}
\end{equation}
Let $\bar{\rho} > 0$ be the far field behavior of density. Assume that the initial data $(\rho_0, u_0)$ satisfies
\begin{equation}
    0 < \underline{\varrho} \le \rho_0 \le \bar{\varrho}, \quad (\rho_0 - \bar{\rho}) \in H^3(\mathbb{R}^N), \quad u_0 \in H^2(\mathbb{R}^N),
\end{equation}
where $\underline{\varrho}$ and $\bar{\varrho}$ are positive constants. Then the Cauchy problem
\begin{equation}\label{NSK_simplified} \begin{cases} \partial_t \rho + \nabla \cdot(\rho u) = 0, \\ \partial_t (\rho u) + \nabla \cdot(\rho u \otimes u) + \nabla P(\rho) = \nabla \cdot \left(2 \rho \mathcal{D}(u) \right) + \nabla \cdot (\rho \nabla \nabla \log \rho). \end{cases} \end{equation}
-\begin{equation}\label{far field}
    \rho \left( x,t \right) \rightarrow \bar{\rho}>0,\quad u\left( x,t \right) \rightarrow 0,\quad \mathrm{as}\, |x|\rightarrow \infty .
\end{equation}
admits a unique global strong solution $(\rho, u)$ satisfying for any $0 < T < \infty$ and $(x,t) \in \mathbb{R}^N \times [0, T]$,
\begin{equation}
