\label{thm:theta-series-form-recall}
For every $L>0$ and $t>0$,
\begin{equation}\label{eq:KL-theta-recall}
K_L(t)=\sum_{n\in\Z}\exp\!\Bigl(-\frac{4\pi^2D}{L^2}\,n^2\,t\Bigr).
\end{equation}
\end{theorem}

