ref_dict.defp:
\begin{definition}\label{defp}
Let us consider some initial data $(\rho_{+,0}^\eps,R_{+,0}^\eps, m_0^\epsilon)\in L^{\gamma_+}\times L^{\gamma_+}\times L^{1}$ for $\gamma_\pm \geq 2$ satisfying the compatibility conditions \eqref{compatibilityeps}, where we defined $\alpha_{\pm,0}^\eps\in [0,1]$, $\rho_{-,0}^\eps\geq 0$, $\rho^\eps_0\geq 0$ and $u_0^\eps$ from $(\rho_{+,0}^\eps,R_{+,0}^\eps, m_0^\epsilon)$ (see Remark \ref{rem.compa}). Let $T>0$. We say that $(\rho_\pm^\eps,\alpha_\pm^\eps,u^\eps)$ is a finite energy weak solution of the compressible two-phase Navier-Stokes system \eqref{system_eps} with algebraic closure on $(0,T)$ associated with the initial data $(\rho_{\pm,0}^\eps, \alpha_{\pm,0}^\eps, u_0^\eps)$ if we have
    \begin{itemize}
        \item the regularity:
        \begin{align*}
            &0 \leq \alpha_+^\eps \leq 1, \quad \ap^\eps + \am^\eps = 1, \quad \rho_\pm^\eps \geq 0, \quad \rho_+^{\gamma_+}=\rho_-^{\gamma_-} \text{   a.e. in } [0,T]\times \Omega,\\
            &\rho_\pm^\eps ,\  \alpha_\pm^\eps \rho_\pm^\eps\in C_{\text{weak}}([0,T]; L^{\gamma_\pm}(\Omega))\cap L^\infty(0,T; L^{\gamma_\pm}(\Omega)),\\
            &\sqrt{\rho^\eps} u^\eps \in  L^\infty(0,T; L^{2}(\Omega)), \quad
             \rho^\eps u^\eps  \in C_{\text{weak}}([0,T]; L^{\frac{2 \gamma_+}{\gamma_++1}}+L^{\frac{2 \gamma_-}{\gamma_-+1}}(\Omega)),\\
             &     u^\eps\in L^2(0,T;H^1_0(\Omega)),
        \end{align*}

        \item the continuity equation:
        \begin{align*}
            \int_\Omega (\alpha_i^\eps \rho_i^\eps \phi)(t,x) \dd x -\int_\Omega (\alpha_{i,0}^\eps \rho_{i,0}^\eps)(x) \phi(0,x) \dd x = \int_0^t \int_\Omega \Big(\alpha_i^\eps \rho_i^\eps(\dt \phi + u^\eps \cdot \nabla \phi)\Big)(s,x) \dd x \dd s,
        \end{align*}
        for a.e. $t\in (0,T)$, for any $\phi \in \mathcal{C}^\infty ([0,T]\times \overline{\Omega})$ and $i=+,-$,
        \item the momentum equation:
        \begin{align*}
            \int_\Omega (\rho^\eps u^\eps)(t,x)\cdot \phi(t,x) dx &- \int_\Omega (\rho^\eps_0 u^\eps_0(x)  \cdot \phi(0,x) dx \\
             =& \int_0^t \int_\Omega \Big( \rho^\eps u^\eps \cdot \dt \phi + \rho^\eps (u^\eps \otimes u^\eps) : \nabla \phi+ \frac{1}{\eps^2} (\rho_+^{\epsilon})^{\gamma_+} \div \phi \Big)(s,x) dx ds \\
            &   -\int_0^t  \int_\Omega \left(\mu \nabla u^\eps : \nabla \phi + (\mu + \lambda) \div u^\eps \div \phi \right)(s,x) dx ds 
        \end{align*}
        for a.e. $t\in (0,T)$, for any $\phi \in \mathcal{C}_c^\infty ([0,T]\times \Omega;\R^3)$,
        \item the energy inequality:
        \begin{align}\label{energy_estimate}
                E(t) +\mu \int_0^t \int_{\Omega}\left( \nabla u^\eps \right)^2 \dd x \dd s +\left(\lambda + \mu\right) \int_0^t \int_{\Omega} (\div u^\eps )^2 \dd x \dd s \leqslant E(0)
        \end{align}
        for a.e. $t \in(0, T)$, where 
        \begin{align}\label{Et}
            E(t) = \int_{\Omega} \frac{1}{2} \Big(\rho^\eps |u^\eps|^2\Big)(t,x) \dd x+\int_{\Omega} \frac{\alpha_{+}^\eps \rho_{+}^{\eps \gamma_{+}}(t,x)}{\epsilon^2(\gamma_{+}-1)} \dd x +\int_{\Omega} \frac{\alpha_-^\eps \rho_{-}^{\eps \gamma_{-}}(t,x)}{\eps^2(\gamma_--1)} \dd x
        \end{align}
    \end{itemize}
\end{definition}

