  for every $e \in E(H)$, where $n=|V(H^\sigma)|$ and~$C$ is a
  suitably large absolute constant. Then
  \begin{equation}
    \label{eq:1}
    \widehat{R}_r(H^\sigma) = O\big(2^{34r}
        r^6 \log^5(r) D^5\log D\big)n.
  \end{equation}
\end{theorem}

