    \]
    in $\mathrm{L}^1(0,+\infty)$. In that case, there exists $\delta>0$ with
    \[
        \liminf_{t\to \infty} \| u^{\lambda^*}(t,\cdot) \|_{\mathrm{L}^1} \geq \delta \quad \text{and} \quad \liminf_{t\to \infty} \| u^{\lambda^*}(t,\cdot) - \overline{\varphi}_2 \|_{\mathrm{L}^1} \geq \delta.
    \]
\end{itemize}

