\begin{enumerate}[label = (\roman*)]
    \item $\beta,\mu \in \L^\infty_+ (0,+\infty)$ and are normalized in the following sense
    \begin{equation}\label{eq:norm}
        \int_0^{+\infty} \beta(a) e^{-\int_0^a \mu(l)\dd l}\dd a = 1.
    \end{equation}
    \item There exists $\underline{\mu}>0$ such that $\mu(a) \geq \underline{\mu}$ for almost every $a\geq 0$.
    \item $f\colon \R_+ \to \R_+$ is a $C^1$-function with bounded derivative such that $f'(x)>0$ for every $x\in \R_+$. It possesses exactly three equilibria, i.e., the equation $f(x)=x$ has the solution set $\{0,\kappa_1,\kappa_2\}$. Also, the relations $f'(0),f'(\kappa_2)<1$ and $f'(\kappa_1)>1$ are valid. See Figure \ref{fig-1}.
    \item Moreover, $f$ verifies
    \begin{equation}\label{diag_cond}
        \limsup_{x\to \infty} \frac{f(x)}{x} < 1.
    \end{equation}
\end{enumerate}
\end{assumption}

