\begin{equation}\label{GM-model}
    \begin{dcases}
    \partial_t u(t,a) + \partial_a u(t,a) = -\mu(a) u(t,a), & t>0,~a>0, \\
    u(t,0) = f\left( \int_0^{+\infty} \beta(a) u(t,a) \dd a \right), & t>0, \\
    u(0,\cdot) = u_0 \in \L^1_+(0,+\infty).
    \end{dcases}
