\|D_{r,y,z}Z(t,x)\|_{2} \leq C_t |z| \int_{\bR} G_{t-r}(x-y')\k(y-y')dy',
\end{equation}
where $C_t>0$ is a constant depending on $t$. Then $\{Z(t,x)\}_{x\in \bR}$ is ergodic.
\end{lemma}

