ref_dict.prop:lambdadecay:
\begin{prop}[Exponential decay at infinity] 
\label{prop:lambdadecay}
Let $1<p<\infty$ and let $\Omega\subseteq\mathbb{R}^N$ be an open set such that $\lambda_{1,p}(\Omega)>0$. For a constant $\lambda$ such that 
\[
\lambda_{1,p}(\Omega)\le \lambda<\mathcal E_p(\Omega),
\] 
we consider $v\in W^{1,p}_0(\Omega)$ a nonnegative subsolution of the equation
\begin{equation}\label{subsol}
-\Delta_p u = \lambda\, u^{p-1},\qquad \text{in}\ \Omega.
\end{equation}
Then:
\begin{itemize}
\item if $\mathcal{E}_p(\Omega)<+\infty$,  there exist two constants $\mathcal{C}=\mathcal{C}(N, p, \lambda, \Omega)>0$ and $\alpha=\alpha(p, \lambda, \Omega)>0$ such that  $v$
satisfies the following decay estimate 
\begin{equation}
\label{decayinfty}
0\le v(x)\le \mathcal{C}\,\|v\|_{L^p(\Omega)}\,e^{-\alpha\,|x|},\qquad \text{for a.\,e.}\ x\in\Omega.
\end{equation}
Moreover, the constant $\alpha$ decreasingly depends on $\lambda$ and we have 
\[
\lim_{\lambda\nearrow \mathcal{E}_p(\Omega)}\alpha=0;
\]
\item if $\mathcal{E}_p(\Omega)=+\infty$, for every $\alpha>0$ there exists a constant $\mathcal{C}=\mathcal{C}(N, p, \lambda, \Omega,\alpha)>0$ such that \eqref{decayinfty} holds.
\end{itemize}
\end{prop}

ref_dict.coro:gradienti:
\begin{coro}
\label{coro:gradienti}
Let $1<p<\infty$ and let $\Omega\subseteq\mathbb{R}^N$ be an open set such that $\lambda_{1,p}(\Omega)>0$. For a constant $\lambda$ such that 
\[
\lambda_{1,p}(\Omega)\le \lambda<\mathcal E_p(\Omega),
\] 
we consider $v\in W^{1,p}_0(\Omega)$ a nonnegative subsolution of the equation \eqref{subsol}.
Then\footnote{We use the notation $\mathcal{C}$ for the same constant of Proposition \ref{prop:lambdadecay}.}:
\begin{itemize}
\item if $\mathcal{E}_p(\Omega)<+\infty$, there exists $M=M(p,\lambda,\Omega)>0$ such that 
 \begin{equation}
\label{decaygrad}
\|\nabla v\|_{L^p(\Omega\setminus B_{R+1})}\le  M\, e^{-\alpha\,R}\,\|v\|_{L^p(\Omega)}, \qquad \text{for every}\ R>0,
\end{equation}
where $\alpha$ is the same exponent as in Proposition \ref{prop:lambdadecay}. Moreover,  for every $0<\beta<\alpha$ there exists a constant  
\[
\widetilde{\mathcal{C}}= \widetilde{\mathcal{C}}(\mathcal{C}, p, \lambda, \beta, \alpha-\beta)>0,
\]
such that 
\begin{equation}
\label{decaygradiente}
\int_{\Omega}\left|\nabla v\right|^{p}\,e^{\beta p|x|}\,dx\le  \widetilde{\mathcal{C}}\,\|v\|^p_{L^{p}(\Omega)};
\end{equation}
\item if $\mathcal{E}_p(\Omega)=+\infty$, for every $\alpha>0$ there exists a constant $M=M(p, \lambda, \Omega,\alpha)>0$ such that \eqref{decaygrad} holds. Moreover,  for every $\beta>0$ there exists a constant  
\[
\widetilde{\mathcal{C}}= \widetilde{\mathcal{C}}(\mathcal{C}, p, \lambda, \beta)>0,
\]
such that \eqref{decaygradiente} holds.
\end{itemize}
In particular, in both cases we have that 
\[
\int_\Omega |\nabla v|^\gamma\,dx<+\infty,\qquad \text{for every}\ 0<\gamma\le p.
\]
\end{coro}

