\EndWhile
\State \Call{CrossBrickStep}{$A,B,\gamma$} \label{line:CrossBrickStep}
\While{$A$ is not on the last row}
    \If{$d_{\mathrm{up}}(B,A)\ge2$}
        \State \Call{StepBelow}{$A,B,\gamma$}
