For $f_1,\ldots,f_l,\, g \in \mathbb{K}\langle \underline{x}\rangle$, the following conditions are equivalent:
\begin{enumerate}
\item[(i)] for all $n \in \mathbb{N}$ and $\underline{X} \in \mathrm{M_n}(\mathbb{K})^d$, joint invariant subspaces for
$f_1(\underline{X}),\ldots,f_l(\underline{X})$ are invariant for $g(\underline{X})$;
\item[(ii)] $g$ belongs to the unital $\mathbb{K}$-algebra generated by $f_1,\ldots,f_l$.
\end{enumerate}
\end{conjecture}

