\begin{thm}[GRH]
\label{thm: main}
Assume GRH holds. For a given geometric form $f$, we construct $(A,\theta)/\C$ such that $f \sim q_{(A,\theta)}$ by following the steps of Algorithms \ref{m: method_1_primitive} and \ref{m: method_2_imprimitive}.
\end{thm}

ref_dict.m: method_2_imprimitive:
\begin{alg}[Imprimitive case] Assume $f$ is an imprimitive geometric form.
\label{m: method_2_imprimitive}
\begin{enumerate}
    \item Apply Algorithm \ref{alg: return_q_imprimitive_g} to $f$, return $q:=q_f$.
     \item Find a triple $(x,y,z) \in \Z^3$ such that $F^B_{f/4}(x,y,z)=p$ is an odd prime and $p \nmid \disc(q):=D$; see Proposition \ref{prop: BW_existence_prime}.   \item  Find a binary form $\Tilde{q} \in \gen(\frac{1}{\cont(q)}q)$ such that $p\in R(\Tilde{q})$; see Lemma \ref{lem: binary_form_represent_p_in_proof}.
\item Apply Algorithm \ref{alg: produce_phi_p} to $F^B_{f/4}$ and the triple $(x,y,z)$ to return a  binary form $\phi_p$ of content $2$ and $\disc(\phi_p) = -4\cont(q)p$ represented by $f/2$. 
\item Apply Algorithm \ref{alg: produce_s=(n,m,k)} to $2\phi_p$ to return a triple $s = (n, m, k)$ with $q_s \sim 2\phi_p$. \item Construction step: Write $E:=\C/\mathcal{O}_{D}$ and $E':=\C/L$, where $L$ is the lattice with the basis $\{p, \frac{-b+\sqrt{\disc(\tilde{q})}}{2}\}$, where $b$ is the $xy$ coefficient of $\tilde{q}(x,y)$. Then put $A:=E\times E'$, and let $\theta:=\textbf{D}(n,m,kh)$, where $h$ is a cyclic isogeny of degree $p\cont(q)$.
\item Verification Step: Use Proposition \ref{prop: ref_hum_computation} for $(A,\theta)$ to find $q_{(A,\theta)}$, and check whether $q_{(A,\theta)} \sim f$ or not.
\end{enumerate}
\end{alg}

ref_dict.prop: ref_hum_computation:
\begin{prop}
\label{prop: ref_hum_computation}
Let $A = E \times E'$ be a CM product surface over $K$. Let $\theta = \textbf{D}(n, m, kh) \in \mathcal{P}(A)$, where $h$ is a cyclic isogeny in $\Hom(E, E')$. Then we have a basis $\{h, h'\}$ of $\Hom(E, E')$, and let $q_{E, E'}(xh + yh') = [a, b, c]$. We also have
\[
q_{(A, \theta)} = \left[ n^2, \ m^2(mn + 3)a, \ b^2k^2 + 4c, \ -2bm(mn + 1), \ -2bkn, \ 2ka(mn + 2) \right].
\]
\end{prop}

ref_dict.p:construction_A:
