\end{equation}
with $L < \lambda_1$. Then the boundary value problem
\begin{equation}\label{eq:Dirichlet}
\begin{cases}
-\Delta_{\mathbb{T}} u + f(x, u(x)) = 0 & \text{in } \Omega,\\\nu = 0 & \text{on } \partial\Omega,
\end{cases}
