theorem.content:
[{\cite[Theorem C]{MR4315549}}]\label{ThmC}
Let \(n \geq 2,\; k,q \geq 1\), and \(r \geq s \geq 1\) with \(\gcd(n,k-1,q)=1\).  
If \(P(r,n,k,s,q)\) is of type \(\widetilde{\mathfrak{Z}}\), then the following are equivalent:
\begin{enumerate}
\item \(P(r,n,k,s,q)\) is perfect;
\item \(|r-s|=1,\; \gcd(n,q)=1,\) and \(\gcd(k-1-qr,n)=1.\)
\end{enumerate}

ref_dict.corD:
\begin{cor}[{\cite[Corollary D]{MR4315549}}]\label{corD}
Let \(n \geq 2,\; k,q \geq 1,\; r \geq s \geq 1\) with \(\gcd(n,k-1,q)=1\).  
If \(P(r,n,k,s,q)\) is of type \(\mathfrak{Z}\), then the following are equivalent:
\begin{enumerate}
\item \(P(r,n,k,s,q)\) is trivial;
\item \(|r-s|=1\) and either \(k \equiv 1 \pmod{n}\) or \(k \equiv 1+q(r-s) \pmod{n}\).
\end{enumerate}
\end{cor}

