ref_dict.cor:gor:
\begin{thm}\label{cor:gor}
    Let $(R,\fm,k)$ be an excellent Cohen--Macaulay local ring of the prime characteristic $p>0$. 
    \begin{enumerate}[label=(\alph*)]
        \item $R$ is tight Buchsbaum if and only if there exists a parameter ideal $\fq\subseteq R$ generated by parameter test elements such that $\fq:\fq^*\supseteq\fm$.\label{cor:gor-1}
        \item  The ring $R$ satisfies condition \ref{a} of \cref{thm:mainthm-restated} if and only if there exists a parameter ideal $$\mathfrak{Q}\subseteq \bigcap_{\fq} (\fq:\fq^F)=:J$$ (where the intersection is taken over all parameter ideals $\fq\subseteq R$) such that $\fm\subseteq \mathfrak{Q}:\mathfrak{Q}^F$. \label{cor:gor-2}
    \end{enumerate}

As Cohen--Macaulay rings are weakly $F$-nilpotent, \cref{cor:gor} shows all conditions of \cref{thm:mainthm} are equivalent in this setting.
\end{thm}

ref_dict.rmk: f-inj + buchs = f-buchs:
\begin{rmk}\label{rmk: f-inj  + buchs = f-buchs}
    Every excellent, $F$-injective generalized Cohen--Macaulay local ring $(R,\fm)$ is $F$-Buchsbaum. Indeed, from \cite[Theorem 1.1]{Ma15}, we know that $\fq=\fq^F$ for all parameter ideals $\fq$ from which we see that $\qs = \fq^{\lim}$. Further from \cite[Theorem~1.2]{Ma15}, it follows that $R$ is Buchsbaum. By \Cref{intro:thm-buchsbaum}, we have that the quantity \[
    e(\mfq)-\ell_R\left(R/\qs\right) = e(\mfq)-\ell_R\left(R/\mfq^{\lim}\right) = e(\mfq)-\ell_R\left(R/\mfq\right)+\ell_R\left(\mfq^{\lim}/\mfq\right)
    \] is a constant independent of $\mfq$.
\end{rmk}

