ref_dict.prp: tbb implies fbb:
\begin{prp}\label{prp: tbb implies fbb}
Suppose $(R,\fm,k)$ is an excellent, unmixed local ring of dimension $d>0$. If $R$ is tight Buchsbaum, then $R$ is also $F$-Buchsbaum.
\end{prp}

ref_dict.thm: CMFI-pun:
\begin{thm}\label{thm: CMFI-pun}(cf. \cite[Theorem 1.1]{GN02})
    Let $(R,\fm)$ be a $d$-dimensional excellent unmixed local ring of prime characteristic $p>0$. The following are equivalent.
    \begin{enumerate}[label=(\alph*)]
        \item For all $\fp\in\Spec(R)\smallsetminus\{\fm\}$, $R_\fp$ is CMFI.\label{thm: CMFI-pun-a}

        \item $R$ is generalized Cohen--Macaulay and $\ell_R\left( 0^F_{H^d_\fm(R)}\right)<\infty$.\label{thm: CMFI-pun-b}

        \item $\sup\{\ell_R ((\fq^{\lim})^F/\fq)  \mid \fq \text { is a parameter ideal} \} < \infty$.\label{thm: CMFI-pun-c}

        \item $\sup\{\ell_R( \qs /\fq)\mid \fq \text{ is a parameter ideal}\}<\infty$.\label{thm: CMFI-pun-c'}

        \item $\sup\{ e(\fq) - \ell_R(R/(\fq^{\lim})^F) \mid \fq \text{ is a parameter ideal} \} < \infty$.\label{thm: CMFI-pun-d}

        \item $\sup\{ e(\fq) - \ell_R(R/\qs) \mid \fq \text{ is a parameter ideal} \} < \infty$. \label{thm: CMFI-pun-d'}
    \end{enumerate}
\end{thm}

