\item Show that an $F$-Buchsbaum ring is Buchsbaum. We first record the following theorem.
\begin{thm}[cf. {\cite[Theorem 3.6]{MQ22}}]\label{thm:(a)<=>(b)}
Let $(R,\fm,k)$ be an excellent, unmixed local ring of dimension $d > 0$. The quantity $\ell_R(\qs/\fq)$ is independent of parameter ideal $\fq$ if and only if  $R$ is $F$-Buchsbaum. Moreover, if $R$ is $F$-Buchsbaum then $R$ is Buchsbaum. 

\end{thm}
\item Prove further that it “satisfies constancy $e(\mathfrak{q}) - \ell_R(R/\mathfrak{q}^F)$”. We first prove the following theorem.
\begin{thm}\label{lem: qs/q constant length implies qF/q constant length}
Let $(R,\fm,k)$ be an excellent, unmixed local ring of prime characteristic $p>0$, and of dimension $d>0$. If $R$ is $F$-Buchsbaum, then:
\begin{enumerate}[label=(\roman*)]
    \item $\qlf = \qs$ for each parameter ideal $\fq$ of $R$;
    \item $\ell_R(\mfq^F/\mfq)$ is a constant independent of parameter ideal $\mfq$;
    \item $e(\fq)-\ell_R(R/\fq^F)$ is a constant independent of  parameter ideal $\fq$.\label{thm:q-f-lim-3}
\end{enumerate}
\end{thm}
\item Conversely, “when $R$ is Buchsbaum and weakly $F$-nilpotent, the constancy of $e(\mathfrak{q}) - \ell_R(R/\mathfrak{q}^F)$ implies that $R$ is $F$-Buchsbaum”. Indeed, we use the following proposition.
\begin{prp}\label{prop:wfn-q-lim-F}
  Let $(R, \fm)$ be a Buchsbaum, weakly $F$-nilpotent local ring of dimension $d>0$. For every parameter ideal $\fq\subseteq R$, we have $\fq^{\lim} \subseteq \fq^F$, and consequently, we have the equality $\qs = \mfq^F = (\mfq^{\lim})^F$.
\end{prp}
\end{itemize}

