	\begin{equation}\label{eq:eul:char:XD:p:ratio}
	\frac{\chi(X'_D)}{\chi(X_D)} =\left\{ 
	\begin{array}{ll}
		1 & \hbox{ if $2 \nmid f$},\\
		3/2 & \hbox{ if $2 \, | \, f$}.
	\end{array}
	\right.
     \end{equation} 
\end{Proposition}

