\begin{proposition}[Dubovitski-Milyoutin, \cite{alexeev2017commande}]\label{dv.yu}
      Let $H$ a Hilbert space, $F$  a real function on $H$ and $M\in C^1(H,H)$. Let $\hat{h}\in H$ be a solution to the optimization problem
      \begin{equation}
          F(\hat{h})=\inf_{h\in H} F(h), \hspace{0.5cm}M(\hat{h})=0.
      \end{equation}
      Then, there exist a $\lambda >0$ and $\zeta\in \text{ker}(M'(\hat{h}))^\bot$     not both zero such that 
      \begin{equation}\label{1.3gaw}
         \lambda F'(\hat{h})+\zeta=0.
      \end{equation}
Observe that if $M$ is a compact operator, then $M'$ is compact and moreover $$\ker M'(\hat{h})^\bot=\text{Rank} (M'(\hat{h}))^*.$$    
  \end{proposition}

