theorem.content:
\label{main1} Let $(M,g)$ be a closed Riemannian $n$-manifold with ${\rm Ric} \geq (n-1)\xi$, ${\rm inj}(M)\geq r_0$, ${\rm diam}(M) \leq D<\infty$. Then there exist positive constants $c(n,D,\xi,r_0,p)$ and $c'(n,D,\xi,r_0,p)$  such that
\begin{equation} \label{eq:vol_lower_bound}
    \lambda_{1,p}(M) \ge \frac{c(n,p,\xi,r_0)}{{V_\xi(D)} . e^{{c'(n,D,\xi,r_0,p)V_\xi(D)}}},
\end{equation}
    where $V_{\xi}(D)$ denotes the volume of a ball of radius $D$ in a space of constant curvature $\xi.$

ref_dict.maincor:
\begin{corollary} \label{maincor}
 Let $(M,g)$ be a closed $n$-manifold with non-negative curvature operator. If the injectivity radius of $(M,g)$ is greater than $r_0$ and the diameter is bounded by $ D$ then there exist positive constants $c(n,p,r_0)$ and $C(n,D,r_0)$ such that the first non-zero eigenvalue $\lambda^C_{1,p}$ of the connection Laplacian $\nabla^{*} \nabla$ acting on the space of $p$-forms satisfies
    \[  \frac{c(n,p,r_0)}{{D^n} . e^{{c'(n,p,r_0)D^n}}}\le \lambda_{1,p}^C\le C(n,D,r_0), \quad {\rm for} \ \ 1 \le p\le n.\]
    \end{corollary}

ref_dict.main1:
\begin{theorem}\label{main1} Let $(M,g)$ be a closed Riemannian $n$-manifold with ${\rm Ric} \geq (n-1)\xi$, ${\rm inj}(M)\geq r_0$, ${\rm diam}(M) \leq D<\infty$. Then there exist positive constants $c(n,D,\xi,r_0,p)$ and $c'(n,D,\xi,r_0,p)$  such that
\begin{equation} \label{eq:vol_lower_bound}
    \lambda_{1,p}(M) \ge \frac{c(n,p,\xi,r_0)}{{V_\xi(D)} . e^{{c'(n,D,\xi,r_0,p)V_\xi(D)}}},
\end{equation}
    where $V_{\xi}(D)$ denotes the volume of a ball of radius $D$ in a space of constant curvature $\xi.$ 
\end{theorem}

ref_dict.thm:volume:
\begin{theorem}
\label{thm:volume}
 Let $(M,g)$ be a closed Riemannian $n$-manifold with volume $V$. Assume that the Ricci curvature satisfies $\mathrm{Ric}_g \ge (n-1)\xi .$ Then   

\[
\lambda_{k,p}
\le
C(n,p)|\xi|^{n/2}(1+r_H^2)\left[\frac{k+1}{\theta_kV}\right]^{\frac{n+1}{n}}.
\]
where $\theta_k=\min\{1,\frac{\omega_n k}{V|\xi|^{\frac{n}{2}}},\frac{\omega_n k}{V|\xi|^{\frac{n}{2}}}(sinh(4r_H\sqrt{|\xi|}))^n\}.$
\end{theorem}

ref_dict.thm:harmonic_radius:
\begin{theorem}{\cite{CheegerAnderson,Hebey}}
\label{thm:harmonic_radius}
Let $(M,g)\in \mathcal{M}(n,\xi,r_0)$. For $n<q<\infty$, there exists a positive constant $r_H=r_H(q, (n,\xi,r_0))<r_0$ such that on any ball of radius $r_H$  a harmonic coordinate chart $\{x_i\}_{i=1}^n$ is defined. If $g_{ij}=g\big{(}\frac{\partial}{\partial x_i},\frac{\partial}{\partial x_j}\big{)}$  then
\begin{enumerate}
    \item $\frac{1}{2}\delta_{ij}\leq g_{ij}\leq 2\delta_{ij}$, and
    \item $r_H^{1-n/q}\|\partial g_{ij}\|_{L^q}\leq 1$.
\end{enumerate}
\end{theorem}

ref_dict.lem:upper_bound_dirichlet_eigenvalue:
\begin{proposition}    \label{lem:upper_bound_dirichlet_eigenvalue}
Let $0<\varepsilon\le r_H$, $(M,g)\in \mathcal{M}(n,\xi,r_0)$ and $x\in M.$ For $B=B(x, \varepsilon)$, there exists a positive constant $C(n,p)$ such that,  
\[\lambda_{0,p}^{D}(B)\leq C(n,p)(1+ r_H^2)\frac{V_\xi(\varepsilon)}{\varepsilon^2 V_\xi(\frac{\varepsilon}{2})}.\]
\end{proposition}

ref_dict.einstein:
\begin{corollary} 
\label{einstein}
Let $(M,g)$ be a closed $n$-manifold with ${\rm inj}(M,g) \ge r_0$, ${\rm diam}(M) \le D <\infty$, $ {\rm Ric}_g = -(n-1)\xi$. Let $\lambda_{k,1}^C$ be the $k$-th eigenvalue of the connection Laplacian $\nabla ^{*} \nabla $. Then there exist positive constants $c(n,D,\xi,r_0)$ and $C(n,D,\xi,r_0)$ depending only on $n,D,\xi,r_0$ such that
  \[c(n,D,\xi,r_0)\le \lambda_{k,1}^C\le C(n,D,\xi,r_0).\]
   \end{corollary}

ref_dict.cor:connectionLap:
\begin{corollary} \label{cor:connectionLap}
    Let $(M,g)$ be a closed $n$-manifold with ${\rm inj}(M,g) \ge r_0$, ${\rm diam}(M) \le D <\infty$, $ {\rm Ric}_g \ge 0$. Then the first non-zero eigenvalue $\lambda^C_{1,1}$ of the connection Laplacian $\nabla^{*} \nabla$ acting on the space of $1$-forms satisfies
    \[c(n,D,r_0)\le \lambda_{1,1}^C\le C(n,D,r_0).\]
\end{corollary}

ref_dict.thm:spectral_equivalence:
\begin{theorem}[Spectral equivalence]
\label{thm:spectral_equivalence}
Let $(M,g)\in \mathcal{M}(n,\xi,r_0)$, and let $X$ be an $\varepsilon$-discretization
with $0<4\varepsilon<r_H$. Then for all degrees $1\le p\le n-1$ and all
\[
1\le k \le |S_p(\mathcal{U}_X)| - \tilde b_p(\mathcal{U}_X),
\]
there exist constants $C_L,C_U>0$, depending only on $(n,p,\xi,r_0,\varepsilon)$,
such that
\begin{equation}\label{eq:spec_equiv}
    C_L\,\lambda_{k,p}(X)
    \;\le\;
    \lambda_{k,p}(M)
    \;\le\;
    C_U\,\lambda_{k,p}(X).
\end{equation}
\end{theorem}

ref_dict.lem:manifoldanddirichlet:
\begin{lemma}
\label{lem:manifoldanddirichlet}    
Let $(M,g)$ be a closed Riemannian $n$-manifold and $D_1,\dots,D_j \subset M$ be pairwise disjoint domains in M. Let $\lambda^{D}_{j,p}(D_i)$ be the eigenvalue of the Hodge Laplacian $\Delta_p$ acting on $p$-forms on $D_i$
with absolute Dirichlet boundary conditions. Then, 
\begin{equation}\label{eq:domain_upper}
\lambda_{jl - 1,p}(M,g)
\;\le\;
\max_{1 \le i \le j} \lambda^{D}_{l-1,p}(D_i) 
\end{equation}
\end{lemma}

ref_dict.thm:main_theorem:
\begin{theorem} \label{thm:main_theorem}
Let $(M,g)$ be a closed Riemannian $n$-manifold with diameter $D$ and harmonic radius greater than $r_H$. Assume that the Ricci curvature satisfies $\mathrm{Ric}_g \ge (n-1)\xi .$  Then there exists a positive constant $C(n,p)$ such that

\[\lambda_{k,p}\le C(n,p)(1+ r_H^2)\frac{V_\xi(\frac{D}{2k})}{ V_\xi(\frac{D}{4k})}\frac{k^2}{D^2},\qquad \forall k\ge\frac{D}{2r_H}\]
and \[\lambda_{k,p}\le C(n,p)(1+ r_H^{-2})\frac{V_\xi(r_H)}{ V_\xi(\frac{r_H}{2})},\qquad \forall k\le \frac{D}{2r_H}.\]
\end{theorem}

ref_dict.lem:PoincareLemma:
\begin{lemma}[Poincar\'e Lemma] \label{lem:PoincareLemma}
    Let $p>0$ and $\mathcal{U}$ be a contractible cover. Let $\omega \in \mathcal{C}^q(\mathcal{U},\Lambda^p)$ such that $d \omega = 0$. Then there exists $\eta \in \mathcal{C}^q(\mathcal{U},\Lambda^{p-1})$ such that $d \eta = \omega$.
\end{lemma}

ref_dict.lem:localspectralgap:
\begin{lemma} \label{lem:localspectralgap}
    Let $0< \varepsilon<\frac{r_H}{4}$, $(M,g) \in \mathcal{M}(n,\xi,r_0)$, and let $X$ an $\varepsilon$-discretization of $(M,g)$ with associated cover $\mathcal{U}_X = \{B(x_i,2 \varepsilon)\}$. For every $0\leq p\le n$ and every $I \in S_p(\mathcal{U}_X)$, the first nonzero eigenvalue of the 
Hodge Laplacian on $U_I$ with absolute boundary conditions satisfies
\begin{equation} \label{eq:localspectralgap}
    \lambda^{\mathrm{abs}}_{1,p}(U_I)
\;\ge\;
\frac{\kappa(n,p)}{\varepsilon^2},
\end{equation}
