System \eqref{ICS} is said to exhibit finite-time flocking if there exists a finite time
	$t_f>0$ such that the following relations hold: 
		\begin{equation} \label{A-1}
		\sup_{i,j\in\mathbb N}\|v_i(t)-v_j(t)\|=0,\quad \forall~ t\ge t_f, \quad \sup_{t\ge0}\sup_{i,j\in\mathbb N}\|x_i(t)-x_j(t)\|<\infty.
                  \end{equation}
Here, the smallest time $t_f$ satisfying \eqref{A-1} is referred to as the flocking time throughout the paper.

ref_dict.T4.1:
\begin{theorem}\label{T4.1}
For $\alpha \in (0, 1)$, let $(x, v)$ be a global solution to \eqref{eq:ICS-switch-sender} with
	$(x^{\rm in}, v^{\rm in})\in \mathcal{B}$. Then, the following assertions hold. \newline
\begin{enumerate}
\item	
If there exists a time $\underline{t}^{(k)}<\infty$ such that
	\begin{equation}\label{eq:int_switch}
		\int_0^{\underline{t}^{(k)}} \psi(a+bs)\,\di s
		= \frac{{\mathcal D}_v^{(k)}(0)^{1-\alpha}}{\kappa(1-\alpha)},
	\end{equation}
	then
	\[
	{\mathcal D}_v^{(k)}(t)=0,\qquad \forall~ t\ge \underline{t}^{(k)}.
	\]
\item	
If we set $t_f:=\max_{k\in[d]} \underline{t}^{(k)},$ then finite-time flocking occurs at $t_f$:
\[ v_i(t)=v_j(t), \quad  x_i(t)-x_j(t)=x_i(t_f)-x_j(t_f),\quad \forall~i,j \in {\mathbb N},~~\forall~ t\ge t_f. \]
\end{enumerate}	
\end{theorem}

