\item $d_{\mathcal{C}(S)}(c^s, c^u) \le k_S \cdot \mathrm{vol}(M) + k_{M\backslash \!\! \backslash S}$, and 
\smallskip
\item $d_{\mathcal{C}(S)}(c^s, c^u) \le k_S \cdot \ell_M(\gamma) + k_{M \backslash \!\! \backslash S}$, where $\gamma$ is any closed geodesic that intersects $S$ essentially and $\ell_M(\gamma)$ is its length in $M$.
\end{enumerate}

