\section{The Proof of Theorem \ref{tp4suffcondi}}\label{toolpf}
\begin{theproof}[Proof of Theorem \ref{tp4suffcondi}]
Let $\rho$ be the spectral radius of $G$. Suppose that $p(x)=x^3-2x^2-3x+4.$ By Lemma \ref{lemrho-p}, we have 
	\begin{align}\label{fA}
		p(\rho) \ge&   \min_{v\in V(G)} \bigg\{\sum_{w\in V(G)}(A^3-2A^2-3A+4I)_{vw}\bigg\}.
	\end{align}

\begin{claim}\label{A3}
For any fixed $i\in V(G)$, we have 	$$\sum_{j\in V(G)}(A^3)_{ij}=d^2(i)+\sum_{k\in N(i)\cup N_2(i)}|N(k)\cap N(i)|\cdot d(k).$$ 
\end{claim}
\begin{proof}
Note that $\sum_{j\in V(G)}(A^3)_{ij}$ is equal to the number of all walks of length three starting from $i$ in $G$. 
Let $S=\{i i_1 i_2 i_3: $ where $i i_1 i_2 i_3$ is a walk of length three starting from $i$ in $G$\}, $S_1=\{i i_1 i_2 i_3\in S: i_2=i\}$ and $S_2=\{i i_1 i_2 i_3\in S: i_2\ne i\}$. 
Then $|S|=\sum_{j\in V(G)}(A^3)_{ij}$.
Note that $|S_1|=d^2(i)$ and 
\begin{align*}
	|S_2|&=\sum_{i_1\in N(i)}\sum_{i_2\in N(i_1)\setminus\{i\}}d(i_2)	= \sum_{k\in N(i)\cup N_2(i)}|N(k)\cap N(i)| \cdot d(k).
\end{align*}
Thus $$\sum_{j\in V(G)}(A^3)_{ij}=|S|=|S_1|+|S_2|=d^2(i)+\sum_{k\in N(i)\cup N_2(i)}|N(k)\cap N(i)| \cdot d(k).$$
Hence, Claim \ref{A3} follows.
 \end{proof}
Combining Inequality (\ref{fA}) with Claim \ref{A3} yields that 
	\begin{align*}
	p(\rho)\ge& \min_{v\in V(G)}  \bigg\{ d^2(v)+\sum_{w\in N(v)\cup N_2(v)}|N(w)\cap N(v)| \cdot d(w)-\sum_{w\in N(v)}2d(w)
	-3d(v)+4 \bigg\}.
	\end{align*}
    By assumptions of Theorem \ref{tp4suffcondi}, we get that $p(\rho)\ge \min_{v\in V(G)} \{F(v)\}\ge 0$. 
Denote the three roots of $p(x)=0$ by $r_1,r_2,r_3$. Let $r_1\ge r_2\ge r_3$. We can see $r_1\cdot r_2\cdot r_3=-4<0$ and so $r_3<0$. 
