theorem.content:
\label{bounded-embedding}
Let $0<p, q<\infty$, $\omega\in\mathcal{D}$, and let $\mu$ be a positive Borel measure on $\mathbb{D}$. For $r\in(0,1)$, write
$$G_{\mu,r}(z):=\frac{\mu(\Delta(z,r))^{\frac{1}{q}}}{\widehat{\omega}(z)^{\frac{1}{p}}(1-|z|)^{\frac{1}{q}}}.$$
\begin{enumerate}
  \item [(1)] If $p\leq q$, then the following conditions are equivalent:
      \begin{enumerate}
          \item [(a)] $I_d:AT^{\infty}_p(\omega)\to T^{\infty}_q(\mu)$ is bounded;
          \item [(b)] $I_d:AT^0_p(\omega)\to T^0_q(\mu)$ is bounded;
          \item [(c)] for some (or any) $r\in(0,1/4)$, $G_{\mu,r}\in L^{\infty}$.
      \end{enumerate}
      Moreover, in these cases,
      $$\|I_d\|\asymp\left\|G_{\mu,r}\right\|_{L^{\infty}}.$$
  \item [(2)] If $p>q$, then the following conditions are equivalent:
      \begin{enumerate}
          \item [(a)] $I_d:AT^{\infty}_p(\omega)\to T^{\infty}_q(\mu)$ is bounded;
          \item [(b)] $I_d:AT^0_p(\omega)\to T^0_q(\mu)$ is bounded;
          \item [(c)] for some (or any) $r\in(0,1/4)$, $G_{\mu,r}\in T^{\infty}_{\frac{pq}{p-q},-1}$.
      \end{enumerate}
      Moreover, in these cases,
      $$\|I_d\|\asymp\left\|G_{\mu,r}\right\|_{T^{\infty}_{\frac{pq}{p-q},-1}}.$$
\end{enumerate}

ref_dict.LP-Volterra:
\begin{proof}
The implications (a)$\Rightarrow$(c) and (b)$\Rightarrow$(c) follow from Lemma \ref{cpt-necessity} and Theorem \ref{bdd-em-2}. Suppose now that (c) holds. Fix $r\in(0,1/4)$ and $s>0$. Let $Z=\{a_k\}\subset\D$ be an $r$-lattice and define $f_t$ as in \eqref{ft} for $c=\{c_k\}\in T^{\infty}_p(Z)$. Then by Theorem \ref{test-function2} and the condition (c), we know that for almost every $t\in[0,1]$,
$$\lim_{|a|\to1^-}\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|f_t(z)|^qd\mu(z)=0.$$
Proceeding as in the proof of Theorem \ref{bdd-em-2}, we can establish that $\{c_kG_{\mu,2r}(a_k)\}\in T^0_q(Z)$. Since $c\in T^{\infty}_p(Z)$ is arbitrary, \cite[Lemma 2.2]{CW22} yields that $\{G_{\mu,2r}(a_k)\}\in T^{0}_{\frac{pq}{p-q}}(Z)$, which together with \eqref{G-inequality} implies that $G_{\mu,r}\in T^0_{\frac{pq}{p-q},-1}$. That is, (d) holds.

Suppose next that (d) holds, i.e. $G_{\mu,r}\in T^0_{\frac{pq}{p-q},-1}$ for some $r\in(0,1/4)$,  and fix $\epsilon>0$. Then by \cite[Lemma 3.1]{CPW}, there exists $\rho\in(0,1)$ such that
$$\sup_{a\in\D}\int_{\D\setminus\rho\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}G_{\mu,r}(u)^{\frac{pq}{p-q}}\frac{dA(u)}{1-|u|}<\epsilon^{\frac{pq}{p-q}}.$$
Let $\{f_j\}\subset AT^{\infty}_p(\omega)$ be a bounded sequence that converges to $0$ uniformly on compact subsets of $\D$. To establish (a), it suffices to show that $\|f_j\|_{T^{\infty}_q(\mu)}\to0$. Since $f_j\to0$ uniformly on $\rho\D$, we may find $J\geq1$ such that $|f_j|<\epsilon$ on $\rho\D$ whenever $j\geq J$. Consequently, for $j\geq J$, similar to \eqref{suff-embedding2}, we have
\begin{align*}
\|f_j\|^q_{T^{\infty}_q(\mu)}
&\lesssim\sup_{a\in\D}\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}
  |f_j(u)|^q\frac{\widehat{\omega}(u)^{\frac{q}{p}}}{(1-|u|)^{\frac{q}{p}}}G_{\mu,r}(u)^q(1-|u|)^{\frac{q}{p}-1}dA(u)\\
&\leq\sup_{a\in\D}\left(\int_{\rho\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|f_j(u)|^p
  \frac{\widehat{\omega}(u)}{1-|u|}dA(u)\right)^{\frac{q}{p}}
  \left\|G_{\mu,r}\right\|^q_{T^{\infty}_{\frac{pq}{p-q},-1}}\\
&\quad +\|f_j\|^q_{AT^{\infty}_p(\omega)}\sup_{a\in\D}\left(\int_{\D\setminus\rho\D}
  \frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}G_{\mu,r}(u)^{\frac{pq}{p-q}}\frac{dA(u)}{1-|u|}\right)^{\frac{p-q}{p}}\\
&\lesssim\epsilon^q.
\end{align*}
Therefore, (a) holds. In this case, the compactness of $I_d:AT^0_p(\omega)\to T^0_q(\mu)$ follows from (a) and Theorem \ref{bdd-em-2}. The proof is complete.
\end{proof}

\section{Littlewood--Paley formulas and integration operators}\label{LP-Volterra}

In this section, we are going to prove Theorems \ref{Littlewood--Paley} and \ref{bounded-Volterra}.

\begin{proof}[Proof of Theorem \ref{Littlewood--Paley}]
Suppose first that (b) holds, i.e. $\omega\in\DDD$. We are going to establish (a). Fix $a\in\D$ and let $\gamma>\big(m+1+\gamma_0(\omega)\big)\max\{1,1/q\}$ be large enough. Assume that $f\in AT^{\infty}_q(\omega)$. Then the reproducing formula
$$f(z)=(\gamma+1)\int_{\D}\frac{(1-|u|^2)^{\gamma}}{(1-\overline{u}z)^{2+\gamma}}f(u)dA(u)$$
gives that
\begin{equation}\label{m-deri}
|f^{(m)}(z)|\lesssim\int_{\D}\frac{(1-|u|)^\gamma}{|1-\overline{u}z|^{2+m+\gamma}}|f(u)|dA(u).
\end{equation}
In the case $q>1$, we can use H\"older's inequality and Lemma \ref{FR} to obtain that
\begin{align*}
|f^{(m)}(z)|^q
&\lesssim\left(\int_{\D}\frac{(1-|u|)^{\gamma}dA(u)}{|1-\overline{u}z|^{2+m+\gamma}}\right)^{\frac{q}{q'}}
  \int_{\D}\frac{(1-|u|)^{\gamma}}{|1-\overline{u}z|^{2+m+\gamma}}|f(u)|^qdA(u)\\
&\lesssim(1-|z|)^{-m\frac{q}{q'}}\int_{\D}\frac{(1-|u|)^{\gamma}}{|1-\overline{u}z|^{2+m+\gamma}}|f(u)|^qdA(u).
\end{align*}
Consequently, for sufficiently small $s>0$, Fubini's theorem together with Lemmas \ref{gFR}(2) and \ref{hat-equivalent} yields that
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|f^{(m)}(z)|^q(1-|z|)^{mq}\omega(z)dA(z)\\
&\ \lesssim\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}\int_{\D}
  \frac{(1-|u|)^{\gamma}}{|1-\overline{u}z|^{2+m+\gamma}}|f(u)|^qdA(u)(1-|z|)^m\omega(z)dA(z)\\
&\ =\int_{\D}(1-|a|)^s(1-|u|)^{\gamma}|f(u)|^q\int_{\D}\frac{(1-|z|)^m\omega(z)dA(z)}
  {|1-\overline{a}z|^{s+1}|1-\overline{u}z|^{2+m+\gamma}}dA(u)\\
&\ \lesssim\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|f(u)|^q\frac{\widehat{\omega}(u)}{1-|u|}dA(u)\\
&\ \asymp\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|f(u)|^q\omega(u)dA(u).
\end{align*}
In the case $0<q\leq1$, the estimate \eqref{m-deri} together with \cite[Proposition 4.17]{Zh07} gives that
$$|f^{(m)}(z)|^q\lesssim\int_{\D}\frac{(1-|u|)^{q(2+\gamma)-2}}{|1-\overline{u}z|^{q(2+m+\gamma)}}|f(u)|^qdA(u).$$
Then, for sufficiently small $s>0$, by Fubini's theorem, Lemmas \ref{gFR}(2) and \ref{hat-equivalent},
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|f^{(m)}(z)|^q(1-|z|)^{mq}\omega(z)dA(z)\\
&\lesssim\int_{\D}(1-|a|)^s(1-|u|)^{q(2+\gamma)-2}|f(u)|^q\int_{\D}\frac{(1-|z|)^{mq}\omega(z)dA(z)}
  {|1-\overline{a}z|^{s+1}|1-\overline{u}z|^{q(2+m+\gamma)}}dA(u)\\
&\lesssim\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|f(u)|^q\frac{\widehat{\omega}(u)}{1-|u|}dA(u)\\
&\asymp\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|f(u)|^q\omega(u)dA(u).
\end{align*}
Since $a\in\D$ is arbitrary, we conclude that in both cases, the function $f^{(m)}(\cdot)(1-|\cdot|)^m$ belongs to $T^{\infty}_q(\omega)$. Moreover,
$$\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)}\lesssim\|f\|_{AT^{\infty}_q(\omega)}.$$
Combining this with Lemma \ref{thm:growth-estimate-unit-disk}, we obtain that
$$\sum_{j=0}^{m-1}\left|f^{(j)}(0)\right|+\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)}
\lesssim\|f\|_{AT^{\infty}_q(\omega)}.$$

Assume now that $f$ is an analytic function on $\D$ such that $f^{(m)}(\cdot)(1-|\cdot|)^m$ belongs to $T^{\infty}_q(\omega)$. Define
$$g(z)=f(z)-\sum_{j=0}^{2m}\frac{f^{(j)}(0)}{j!}z^j.$$
It is clear that any bounded function belongs to $T^{\infty}_q(\omega)$, and by Lemma \ref{thm:growth-estimate-unit-disk},
\begin{equation}\label{j-deritive-0}
|f^{(j)}(0)|\lesssim\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)},\quad m\leq j\leq2m.
\end{equation}
Then we have $g^{(m)}(\cdot)(1-|\cdot|)^m$ is in $T^{\infty}_q(\omega)$, and
\begin{align*}
\left\|g^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)}
&\lesssim\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)}+
  \sum_{j=m}^{2m}\left|f^{(j)}(0)\right|\\
&\lesssim\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)}.
\end{align*}
Since
$$g(0)=g'(0)=\cdots=g^{(2m)}(0)=0,$$
we may apply \cite[Proposition 4.27]{Zh07} to obtain that
$$g(z)=\frac{1}{(\gamma+2)\cdots(\gamma+m)}\int_{\D}\frac{(1-|u|^2)^{m+\gamma}}{\overline{u}^m(1-\overline{u}z)^{2+\gamma}}g^{(m)}(u)dA(u),\quad z\in\D.$$
Noting that the function $u\mapsto u^{-m}g^{(m)}(u)$ is analytic on $\D$, the above representation together with \cite[Lemma 4.26]{Zh07} gives that
\begin{equation}\label{m-inte}
|g(z)|\lesssim\int_{\D}\frac{(1-|u|)^{m+\gamma}}{|1-\overline{u}z|^{2+\gamma}}\left|g^{(m)}(u)\right|dA(u).
\end{equation}
In the case $q>1$, by H\"older's inequality and Lemma \ref{FR}, we have for sufficiently small $\epsilon>0$,
\begin{align*}
|g(z)|^q
&\lesssim\left(\int_{\D}\frac{(1-|u|)^{\gamma-\epsilon q'}dA(u)}{|1-\overline{u}z|^{2+\gamma}}\right)^{\frac{q}{q'}}
  \int_{\D}\frac{(1-|u|)^{mq+\gamma+\epsilon q}}{|1-\overline{u}z|^{2+\gamma}}\left|g^{(m)}(u)\right|^qdA(u)\\
&\lesssim(1-|z|)^{-\epsilon q}
  \int_{\D}\frac{(1-|u|)^{mq+\gamma+\epsilon q}}{|1-\overline{u}z|^{2+\gamma}}\left|g^{(m)}(u)\right|^qdA(u).
\end{align*}
Then for sufficinetly small $s>0$, by Fubini's theorem, Lemmas \ref{gFR}(2) and \ref{hat-equivalent},
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|g(z)|^q\omega(z)dA(z)\\
&\lesssim\int_{\D}(1-|a|)^s(1-|u|)^{mq+\gamma+\epsilon q}\left|g^{(m)}(u)\right|^q
  \int_{\D}\frac{(1-|z|)^{-\epsilon q}\omega(z)dA(z)}{|1-\overline{a}z|^{s+1}|1-\overline{u}z|^{2+\gamma}}dA(u)\\
&\lesssim\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}\left|g^{(m)}(u)\right|^q(1-|u|)^{mq-1}
  \widehat{\omega}(u)dA(u)\\
&\asymp\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}\left|g^{(m)}(u)\right|^q(1-|u|)^{mq}
  \omega(u)dA(u)\\
&\lesssim\left\|g^{(m)}(\cdot)(1-|\cdot|)^m\right\|^q_{T^{\infty}_q(\omega)}\lesssim\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|^q_{T^{\infty}_q(\omega)}.
\end{align*}
In the case $0<q<1$, by \eqref{m-inte} and \cite[Proposition 4.17]{Zh07},
$$|g(z)|^q\lesssim\int_{\D}\frac{(1-|u|)^{(2+\gamma+m)q-2}}{|1-\overline{u}z|^{(2+\gamma)q}}
\left|g^{(m)}(u)\right|^qdA(u),$$
and similarly as before, for sufficiently small $s>0$,
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|g(z)|^q\omega(z)dA(z)\\
&\lesssim\int_{\D}(1-|a|)^s(1-|u|)^{(2+\gamma+m)q-2}\left|g^{(m)}(u)\right|^q
  \int_{\D}\frac{\omega(z)dA(z)}{|1-\overline{a}z|^{s+1}|1-\overline{u}z|^{(2+\gamma)q}}dA(u)\\
&\lesssim\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}\left|g^{(m)}(u)\right|^q(1-|u|)^{mq-1}
  \widehat{\omega}(u)dA(u)\\
&\asymp\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}\left|g^{(m)}(u)\right|^q(1-|u|)^{mq}
  \omega(u)dA(u)\\
&\lesssim\left\|g^{(m)}(\cdot)(1-|\cdot|)^m\right\|^q_{T^{\infty}_q(\omega)}\lesssim\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|^q_{T^{\infty}_q(\omega)}.
\end{align*}
Consequently, in both cases, $g\in AT^{\infty}_q(\omega)$, and
$$\|g\|_{AT^{\infty}_{q}(\omega)}\lesssim\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)}.$$
Therefore, by the definition of $g$ and \eqref{j-deritive-0}, we obtain that $f\in AT^{\infty}_q(\omega)$, and
\begin{align*}
\|f\|_{AT^{\infty}_q(\omega)}
&=\left\|g(\cdot)+\sum_{j=0}^{2m}\frac{f^{(j)}(0)}{j!}(\cdot)^j\right\|_{AT^{\infty}_q(\omega)}\lesssim\|g\|_{AT^{\infty}_q(\omega)}+\sum_{j=0}^{2m}\left|f^{(j)}(0)\right|\\
&\lesssim\sum_{j=0}^{m-1}\left|f^{(j)}(0)\right|+\left\|f^{(m)}(\cdot)(1-|\cdot|)^m\right\|_{T^{\infty}_q(\omega)}.
\end{align*}

Suppose next that (a) holds. We are going to show $\omega \in \DDD$. For $x>0$, write
$$\omega_x:=\int_0^1r^x\omega(r)dr.$$
Consider the test functions $f_n(z)=z^n$ for $n\in\mathbb{N}$. An elementary computation gives that
$$\|f_n\|_{AT_q^\infty(\omega)}^q \asymp \omega_{nq+1},$$
and
$$\left\|f'_n(\cdot)(1-|\cdot|)\right\|^q_{T^{\infty}_q(\omega)}\asymp
n^q\int_0^1r^{(n-1)q+1}(1-r)^q\omega(r)dr,$$
where the implicit constants are both independent of $n$. Then by the condition (a), for any $n\in\mathbb{N}$,
$$n^q\int_0^1r^{(n-1)q+1}(1-r)^q\omega(r)dr\asymp\omega_{nq+1}.$$
It is clear that $\omega_{nq+1}\leq\omega_{(n-1)q+1}$, we obtain that there exists $C>0$ such that
$$n^q\int_0^1r^{(n-1)q+1}(1-r)^q\omega(r)dr\leq C\omega_{(n-1)q+1},\quad \forall n\in\mathbb{N},$$
which gives $\omega\in\DD$ (see the proof of \cite[Theorem 6]{PR21}). Consequently,
$$\omega_{(n-1)q+1}\asymp\omega_{nq+1}\asymp n^q\int_0^1r^{(n-1)q+1}(1-r)^q\omega(r)dr$$
holds for any $n\in\mathbb{N}$ with implicit constants independent of $n$, which in turn implies that $\omega\in\DDD$ (see the proof of \cite[Theorem 5]{PR21}). The general case $m\in \N$ readily follows from the argument above. The proof is finished.
\end{proof}

ref_dict.atomic-decomposition:
\begin{align}\label{rrr}
       |1-\overline{a}z| &\leq |1-r^2\overline{a}z| + |r^2\overline{a}z - \overline{a}z| \leq |1-r^2\overline{a}z| + (1-r^2)\nonumber \\
        &\leq |1-r^2\overline{a}z| + (1-r^2|a||z|) \leq 2|1-r^2\overline{a}z|.
\end{align}
Since $\gamma\geq m+1+\gamma_0(\omega)$ and $\delta\in[-m,\delta_0)$, we can apply \eqref{rrr} and Lemma \ref{elementary}(c) to obtain that
\begin{align*}
I_2(a,z)&=\int_0^1\frac{(1-r)^{-\delta}\omega(r)dr}{(1-r^2|z|^2)^{\gamma-1}|1-r^2\overline{a}z|^s}\\
&\lesssim\frac{1}{|1-\overline{a}z|^s}\left(\int_0^{|z|}\frac{\omega(r)dr}{(1-r)^{\gamma+\delta-1}}
    +\frac{1}{(1-|z|)^{\gamma-1}}\int_{|z|}^1\frac{\omega(r)dr}{(1-r)^{\delta}}\right)\\
&\lesssim\frac{1}{|1-\overline{a}z|^s}\left(\frac{\widehat{\omega}(z)}{(1-|z|)^{\gamma+\delta-1}}
    +\frac{1}{(1-|z|)^{\gamma-1+\delta-\delta_0}}\int_{|z|}^1\frac{\omega(r)dr}{(1-r)^{\delta_0}}\right).
\end{align*}
Integrating by parts and applying Lemma \ref{elementary-Dcheck} and \eqref{hat-integral}, we obtain that
$$\int_{|z|}^1\frac{\omega(r)dr}{(1-r)^{\delta_0}}=\frac{\widehat{\omega}(z)}{(1-|z|)^{\delta_0}}+\delta_0\int_{|z|}^1\frac{\widehat{\omega}(r)}{(1-|z|)^{1+\delta_0}}dr\lesssim\frac{\widehat{\omega}(z)}{(1-|z|)^{\delta_0}},$$
which gives that
$$I_2(a,z)\lesssim\frac{\widehat{\omega}(z)}{|1-\overline{a}z|^s(1-|z|)^{\gamma+\delta-1}}.$$
It remains to estimate $I_1(a,z)$. Noting that $s+\delta_0-1<\min\{\alpha_0(\omega),\tau_0(\omega)\}$ and $s<\gamma$, integrating by parts and using Lemma \ref{elementary-Dcheck} and \eqref{hat-integral}, we obtain that
\begin{align*}
&\int_{|z|}^1\frac{(1-r)^{-\delta}\omega(r)dr}{(1-r|a|)^{s-1}(1-r|a||z|)^{\gamma-s}}\\
&\leq\frac{1}{(1-|z|)^{\gamma-s+\delta-\delta_0}}\int_{|z|}^1\frac{\omega(r)dr}{(1-r)^{s+\delta_0-1}}\\
&=\frac{1}{(1-|z|)^{\gamma-s+\delta-\delta_0}}\left(\frac{\widehat{\omega}(z)}{(1-|z|)^{s+\delta_0-1}}+(s+\delta_0-1)\int_{|z|}^1\frac{\widehat{\omega}(r)dr}{(1-r)^{s+\delta_0}}\right)\\
&\lesssim\frac{\widehat{\omega}(z)}{(1-|z|)^{\gamma+\delta-1}}.
\end{align*}
This, together with \eqref{rrr} and Lemma \ref{elementary}(c), gives that
\begin{align*}
I_1(a,z)&=\int_0^1\frac{(1-r)^{-\delta}\omega(r)dr}{(1-r^2|a|^2)^{s-1}|1-r^2\overline{a}z|^{\gamma}}\\
&\lesssim\frac{1}{|1-\overline{a}z|^s}\left(\int_0^{|z|}+\int_{|z|}^1\right)\frac{(1-r)^{-\delta}\omega(r)dr}{(1-r|a|)^{s-1}(1-r|a||z|)^{\gamma-s}}\\
&\lesssim\frac{1}{|1-\overline{a}z|^s}\left(\int_0^{|z|}\frac{\omega(r)dr}{(1-r)^{\gamma+\delta-1}}+\frac{\widehat{\omega}(z)}{(1-|z|)^{\gamma+\delta-1}}\right)\\
&\lesssim\frac{\widehat{\omega}(z)}{|1-\overline{a}z|^s(1-|z|)^{\gamma+\delta-1}},
\end{align*}
which finishes the proof.
\end{proof}

\section{Atomic decomposition}\label{atomic-decomposition}

In this section, we are going to establish the atomic decomposition for the analytic tent spaces $AT^{\infty}_q(\omega)$ and $AT^0_q(\omega)$ induced by $\omega\in\DDD$, which will be useful when we deal with the embedding theorems.

Before proceeding, recall that for $r\in(0,1)$, a sequence $Z=\{a_k\}\subset\D$ is said to be an $r$-lattice (in the pseudo-hyperbolic metric) if $\D=\bigcup_{k\geq1}\Delta(a_k,r)$ and $d(a_k,a_j)\geq r/2$ for $k\neq j$. By \cite[Lemma 4.8]{Zh07}, $r$-lattice exists for any $r\in(0,1)$. Moreover, there exists a positive integer $N$ such that for any $r$-lattice $Z=\{a_k\}$ with $r\in(0,1/4)$, each point $z\in\D$ belongs to at most $N$ of the sets $\Delta(a_k,2r)$.

Given an $r$-lattice $Z=\{a_k\}$ and $0<q<\infty$, the sequence tent space $T^{\infty}_q(Z)$ consists of sequences $c=\{c_k\}$ such that
$$\|c\|_{T^{\infty}_q(Z)}^q:
=\esssup_{\xi\in\T}\left(\sup_{a\in\Gamma(\xi)}\frac{1}{1-|a|}\sum_{a_k\in S(a)}|c_k|^q(1-|a_k|)\right)<\infty.$$
Analogously, $T^0_q(Z)$ is the subspace of $T^{\infty}_q(Z)$ consisting of sequences $c=\{c_k\}$ with
$$\lim_{|a|\to1^-}\frac{1}{1-|a|}\sum_{a_k\in S(a)}|c_k|^q(1-|a_k|)=0.$$
As before, we have that a sequence $c=\{c_k\}$ belongs to $T^{\infty}_q(Z)$ (resp. $T^0_q(Z)$) if and only if the measure $d\nu_c:=\sum_{k}|c_k|^q(1-|a_k|)\delta_{a_k}$ is a (resp. vanishing) Carleson measure, where $\delta_{a_k}$ is the Dirac point mass at $a_k$. Moreover, $\|c\|_{T^{\infty}_q(Z)}=\|\nu_c\|_{CM}^{1/q}$.

The main result of this section is as follows, which establishes the atomic decomposition for the analytic tent spaces $AT^{\infty}_q(\omega)$.

\begin{theorem}\label{test-function2}
Let $\omega\in\DDD$, $0<q<\infty$, $\gamma>\big(1+\gamma_0(\omega)\big)\max\left\{1,1/q\right\}$, and let $Z=\{a_k\}$ be an $r$-lattice for some $r\in(0,1/4)$. Then
\begin{enumerate}
    \item [(1)] for any $c=\{c_k\}\in T^{\infty}_q(Z)$, the function
    $$f(z)=\sum_{k\geq1}c_k\frac{(1-|a_k|)^{\gamma}}{\widehat{\omega}(a_k)^{\frac{1}{q}}(1-\overline{a_k}z)^{\gamma}},\quad z\in\D$$
    belongs to $AT^{\infty}_q(\omega)$, and $\|f\|_{AT^{\infty}_q(\omega)}\lesssim\|c\|_{T^{\infty}_q(Z)}$;
    \item [(2)] there exists an $r'$-lattice $Z'=\{z_k\}$ for some sufficiently small $r'\in(0,1/4)$ such that, any $f\in AT^{\infty}_q(\omega)$ has the form
    $$f(z)=\sum_{k\geq1}c_k\frac{(1-|z_k|)^{\gamma}}{\widehat{\omega}(z_k)^{\frac{1}{q}}(1-\overline{z_k}z)^{\gamma}},$$
    where $c=\{c_k\}\in T^{\infty}_q(Z')$ with $\|c\|_{T^{\infty}_q(Z')}\lesssim\|f\|_{AT^{\infty}_q(\omega)}$.
\end{enumerate}
\end{theorem}
\begin{proof}
(1) Fix $a\in\D$. In the case $0<q\leq1$, we have
$$|f(z)|^q\leq\sum_{k\geq1}|c_k|^q\frac{(1-|a_k|)^{q\gamma}}{\widehat{\omega}(a_k)|1-\overline{a_k}z|^{q\gamma}}.$$
Then for sufficiently small $s>0$, Lemma \ref{gFR}(2) with $m=0$ yields that
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|f(z)|^q\omega(z)dA(z)\\
&\ \leq\sum_{k\geq1}|c_k|^q\frac{(1-|a|)^s(1-|a_k|)^{q\gamma}}{\widehat{\omega}(a_k)}
  \int_{\D}\frac{\omega(z)dA(z)}{|1-\overline{a}z|^{s+1}|1-\overline{a_k}z|^{q\gamma}}\\
&\ \lesssim\sum_{k\geq1}\frac{(1-|a|)^s}{|1-\overline{a}a_k|^{s+1}}|c_k|^q(1-|a_k|)\ \lesssim\|c\|^q_{T^{\infty}_q(Z)}.
\end{align*}
Note that for sufficiently small $\epsilon>0$, the sub-harmonic property together with Lemma \ref{FR} gives that
\begin{align*}
\sum_{k\geq1}\frac{(1-|a_k|)^{\gamma-\epsilon}}{|1-\overline{a_k}z|^{\gamma}}
&\lesssim\sum_{k\geq1}(1-|a_k|)^{\gamma-2-\epsilon}\int_{\Delta(a_k,r)}\frac{dA(u)}{|1-\overline{u}z|^{\gamma}}\\
&\lesssim\int_{\D}\frac{(1-|u|)^{\gamma-2-\epsilon}}{|1-\overline{u}z|^{\gamma}}dA(u)\\
&\asymp(1-|z|)^{-\epsilon}.
\end{align*}
Hence in the case $q>1$, we can use H\"older's inequality to obtain that for sufficiently small $\epsilon>0$,
\begin{align*}
|f(z)|^q&\leq\left(\sum_{k\geq1}\frac{(1-|a_k|)^{\gamma-\epsilon}}{|1-\overline{a_k}z|^{\gamma}}\right)^{\frac{q}{q'}}\cdot
    \sum_{k\geq1}|c_k|^q\frac{(1-|a_k|)^{\gamma+(q-1)\epsilon}}{\widehat{\omega}(a_k)|1-\overline{a_k}z|^{\gamma}}\\
&\lesssim(1-|z|)^{-(q-1)\epsilon}\sum_{k\geq1}|c_k|^q\frac{(1-|a_k|)^{\gamma+(q-1)\epsilon}}{\widehat{\omega}(a_k)|1-\overline{a_k}z|^{\gamma}},
\end{align*}
which, combined with Lemma \ref{gFR}(2), gives that
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|f(z)|^q\omega(z)dA(z)\\
&\ \lesssim\sum_{k\geq1}|c_k|^q\frac{(1-|a|)^s(1-|a_k|)^{\gamma+(q-1)\epsilon}}{\widehat{\omega}(a_k)}
    \int_{\D}\frac{(1-|z|)^{-(q-1)\epsilon}\omega(z)dA(z)}{|1-\overline{a}z|^{s+1}|1-\overline{a_k}z|^{\gamma}}\\
&\ \lesssim\sum_{k\geq1}\frac{(1-|a|)^s}{|1-\overline{a}a_k|^{s+1}}|c_k|^q(1-|a_k|)\ \lesssim\|c\|^q_{T^{\infty}_q(Z)}.
\end{align*}
Since $a\in\D$ is arbitrary, in both cases, we have $f\in AT^{\infty}_q(\omega)$, and $\|f\|_{AT^{\infty}_q(\omega)}\lesssim\|c\|_{T^{\infty}_q(Z)}$.

(2) Let $r'$ be small enough in the sense that $r'/r$ is small. Then we can construct an $r'$-lattice $Z'=\{a_{kj}\}_{1\leq k<\infty,1\leq j\leq J}$ and a disjoint decomposition
$$\D=\bigcup_{k=1}^{\infty}\bigcup_{j=1}^JD_{kj}$$
of $\D$ such that $a_{kj}\in\Delta(a_k,r)$ and $D_{kj}\subset\Delta(a_k,r)$ for any $k\geq1$ and $1\leq j\leq J$; see \cite[p. 64]{Zh05} for the details.

Define an operator $S$ on $\mathcal{H}(\D)$ by
$$Sf(z)=\sum_{k=1}^{\infty}\sum_{j=1}^J\frac{f(a_{kj})}{(1-\overline{a_{kj}}z)^{\gamma}}
\int_{D_{kj}}(1-|z|)^{\gamma-2}dA(z).$$
By \cite[Lemma 2.29]{Zh05} and \eqref{D-constant}, there exist constants $C_1,C_2>0$, independent of $r'$ and $r$, such that
\begin{align*}
&|f(z)-Sf(z)|\\
&\ \leq C_1\eta\sum_{k=1}^{\infty}\frac{(1-|a_k|)^{\gamma-\frac{2}{q}}}{|1-\overline{a_k}z|^{\gamma}}
    \left(\int_{\Delta(a_k,2r)}|f(u)|^qdA(u)\right)^{\frac{1}{q}}\\
&\ \leq C_2\eta\sum_{k=1}^{\infty}\frac{(1-|a_k|)^{\gamma}}{\widehat{\omega}(a_k)^{\frac{1}{q}}
    |1-\overline{a_k}z|^{\gamma}}
    \left(\int_{\Delta(a_k,2r)}|f(u)|^q\frac{\widehat{\omega}(u)}{(1-|u|)^2}dA(u)\right)^{\frac{1}{q}}
\end{align*}
for all $z\in\D$ and $f\in \mathcal{H}(\D)$, where $\eta=\tanh^{-1}r'+r'r^{2n(1-\frac{1}{q})-1}$. Then by (1) and Lemma \ref{hat-equivalent}, for any $s>0$,
\begin{align*}
&\|f-Sf\|_{AT^{\infty}_q(\omega)}\\
&\leq C_3\eta\left(\sup_{a\in\D}\sum_{k=1}^{\infty}\frac{(1-|a|)^s(1-|a_k|)}{|1-\overline{a}a_k|^{s+1}}
    \int_{\Delta(a_k,2r)}|f(u)|^q\frac{\widehat{\omega}(u)}{(1-|u|)^2}dA(u)\right)^{1/q}\\
&\leq C_4N\eta\left(\sup_{a\in\D}\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|f(u)|^q
    \frac{\widehat{\omega}(u)}{1-|u|}dA(u)\right)^{1/q}\\
&\leq C_5N\eta\|f\|_{AT^{\infty}_q(\omega)},
\end{align*}
where $C_3,C_4,C_5$ are all independent of $r'$ and $r$. Hence we can choose $r'$ small enough so that $C_5N\eta<1$ and consequently, the operator $S$ is invertible on $AT^{\infty}_q(\omega)$. Then for any $f\in AT^{\infty}_q(\omega)$, there exists $g\in AT^{\infty}_q(\omega)$ such that
$$f(z)=Sg(z)=\sum_{k=1}^{\infty}\sum_{j=1}^Jc_{kj}\frac{(1-|a_{kj}|)^{\gamma}}{\widehat{\omega}(a_{kj})^{\frac{1}{q}}(1-\overline{a_{kj}}z)^{\gamma}},$$
where
$$c_{kj}=g(a_{kj})\widehat{\omega}(a_{kj})^{\frac{1}{q}}(1-|a_{kj}|)^{-\gamma}\int_{D_{kj}}(1-|z|)^{\gamma-2}dA(z).$$
It remains to show that the sequence $c=\{c_{kj}\}$ belongs to $T^{\infty}_q(Z')$. In fact, since $D_{kj}\subset\Delta(a_k,r)$ and $a_{kj}\in\Delta(a_k,r)$, we deduce from the sub-harmonic property of $|g|^q$ and \eqref{D-constant} that
$$|c_{kj}|^q\lesssim\frac{1}{1-|a_{kj}|}\int_{\Delta(a_k,2r)}|g(u)|^q\frac{\widehat{\omega}(u)}{1-|u|}dA(u),$$
which, together with Lemma \ref{hat-equivalent}, implies that for any $s>0$ and $a\in\D$,
\begin{align*}
&\sum_{k=1}^{\infty}\sum_{j=1}^J\frac{(1-|a|)^s}{|1-\overline{a}a_{kj}|^{s+1}}|c_{kj}|^q(1-|a_{kj}|)\\
&\ \lesssim J\sum_{k=1}^{\infty}\frac{(1-|a|)^s}{|1-\overline{a}a_k|^{s+1}}\int_{\Delta(a_k,2r)}|g(u)|^q
    \frac{\widehat{\omega}(u)}{1-|u|}dA(u)\\
&\ \lesssim NJ\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|g(u)|^q\frac{\widehat{\omega}(u)}{1-|u|}dA(u)\\
&\ \lesssim NJ\|g\|^q_{AT^{\infty}_q(\omega)}\\
&\ \leq NJ\|S^{-1}\|^q\|f\|^q_{AT^{\infty}_q(\omega)}.
\end{align*}
Therefore, $c=\{c_{kj}\}\in T^{\infty}_q(Z')$ and $\|c\|_{T^{\infty}_q(Z')}\lesssim\|f\|_{AT^{\infty}_q(\omega)}$. The proof is complete.
\end{proof}

Using the same method, we can also establish the atomic decomposition for the spaces $AT^0_q(\omega)$.

\begin{theorem}\label{atom2}
Let $\omega\in\DDD$, $0<q<\infty$, $\gamma>\big(1+\gamma_0(\omega)\big)\max\left\{1,1/q\right\}$. Then there exists an $r$-lattice $Z=\{a_k\}$ such that the space $AT^0_q(\omega)$ consists exactly of functions of the form
    $$f(z)=\sum_{k\geq1}c_k\frac{(1-|a_k|)^{\gamma}}{\widehat{\omega}(a_k)^{\frac{1}{q}}(1-\overline{a_k}z)^{\gamma}},\quad z\in\D,$$
where $\{c_k\}\in T^0_q(Z)$.
\end{theorem}

As an application of Theorem \ref{test-function2}, we can determine the behavior of the dilation of functions in $AT^{\infty}_q(\omega)$. For an analytic function $f$ on $\D$ and $\rho\in(0,1)$, the dilation $f_{\rho}$ is defined by $f_{\rho}(z):=f(\rho z)$ for $z\in\D$.

\begin{corollary}\label{dilation}
Let $0<q<\infty$, $\omega\in\DDD$ and $f\in AT^{\infty}_q(\omega)$. Then for any $\rho\in(0,1)$, $\|f_{\rho}\|_{AT^{\infty}_q(\omega)}\lesssim\|f\|_{AT^{\infty}_q(\omega)}$.
\end{corollary}
\begin{proof}
Fix $\gamma>\big(1+\beta_0(\omega)+\gamma_0(\omega)\big)\max\{1,1/q\}$. Then by Theorem \ref{test-function2}, there exist an $r$-lattice $Z=\{z_k\}$ for some sufficiently small $r\in(0,1/4)$ and a sequence $c=\{c_k\}\in T^{\infty}_q(Z)$ such that
$$f(z)=\sum_{k\geq1}c_k\frac{(1-|z_k|)^{\gamma}}{\widehat{\omega}(z_k)^{\frac{1}{q}}(1-\overline{z_k}z)^{\gamma}}$$
and $\|c\|_{T^{\infty}_q(Z)}\asymp\|f\|_{AT^{\infty}_q(\omega)}$. Consequently,
$$f_{\rho}(z)=\sum_{k\geq1}c_k\frac{(1-|z_k|)^{\gamma}}{\widehat{\omega}(z_k)^{\frac{1}{q}}(1-\overline{z_k}\rho z)^{\gamma}}.$$
In the case $0<q\leq1$, we can use Lemma \ref{gFR} similarly as in the proof of Theorem \ref{test-function2}(1) to obtain that for any $a\in\D$ and sufficiently small $s>0$,
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|f_{\rho}(z)|^q\omega(z)dA(z)\\
&\ \leq\sum_{k\geq1}|c_k|^q\frac{(1-|a|)^s(1-|z_k|)^{q\gamma}}{\widehat{\omega}(z_k)}
  \int_{\D}\frac{\omega(z)dA(z)}{|1-\overline{a}z|^{s+1}|1-\overline{\rho z_k}z|^{q\gamma}}\\
&\ \lesssim\sum_{k\geq1}\frac{(1-|a|)^s}{|1-\overline{\rho a}z_k|^{s+1}}|c_k|^q
  \frac{(1-|z_k|)^{q\gamma}}{(1-\rho|z_k|)^{q\gamma-1}}\frac{\widehat{\omega}(\rho z_k)}{\widehat{\omega}(z_k)},
\end{align*}
which, combined with Lemma \ref{elementary}(b) and the fact that $q\gamma-\beta_0(\omega)-1>0$, implies that
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}|f_{\rho}(z)|^q\omega(z)dA(z)\\
&\ \lesssim\sum_{k\geq1}\frac{(1-|a|)^s}{|1-\overline{\rho a}z_k|^{s+1}}|c_k|^q
  \frac{(1-|z_k|)^{q\gamma-\beta_0(\omega)}}{(1-\rho|z_k|)^{q\gamma-\beta_0(\omega)-1}}\\
&\ \leq\sum_{k\geq1}\frac{(1-|\rho a|)^s}{|1-\overline{\rho a}z_k|^{s+1}}|c_k|^q(1-|z_k|).
\end{align*}
Therefore, $\|f_{\rho}\|_{AT^{\infty}_q(\omega)}\lesssim\|c\|_{T^{\infty}_q(Z)}\asymp\|f\|_{AT^{\infty}_q(\omega)}$. The case $q>1$ is similar and we omit the details.
\end{proof}

\section{Embedding theorems}\label{embedding-theorems}

The purpose of this section is to characterize the bounded and compact embeddings $I_d:AT^{\infty}_p(\omega)\to T^{\infty}_q(\mu)$. To this end, we need two auxiliary results. The first one establishes the growth estimates for the derivatives of functions in $AT^{\infty}_q(\omega)$, and the second one gives a family of test functions in $AT^{\infty}_q(\omega)$.

\begin{lemma}\label{thm:growth-estimate-unit-disk}
Let $0 < q < \infty$, $\omega \in \mathcal{D}$, $m\in\mathbb{N}_0$ and $f \in AT_{q}^{\infty}(\omega)$. Then for any $z\in\D$,
$$
|f^{(m)}(z)| \lesssim \frac{\|f\|_{AT_{q}^{\infty}(\omega)}}{\widehat{\omega}(z)^{1/q}(1-|z|)^m}.
$$
\end{lemma}
\begin{proof}
Fix $s>0$. By the sub-harmonic property of $|f|^q$, \eqref{D-constant} and Lemma \ref{hat-equivalent}, we have
\begin{align*}
|f(z)|^q &\lesssim \frac{1}{(1-|z|)^2} \int_{\Delta(z,r)} |f(u)|^q  dA(u)\\
&\lesssim \frac{1}{\widehat{\omega}(z)(1-|z|)} \int_{\Delta(z,r)} |f(u)|^q
  \frac{\widehat{\omega}(u)}{1-|u|}dA(u)\\
&\asymp\frac{1}{\widehat{\omega}(z)}\int_{\Delta(z,r)}
  \frac{(1-|z|)^{s}}{|1-\overline{z}u|^{s+1}}|f(u)|^q\frac{\widehat{\omega}(u)}{1-|u|}dA(u)\\
&\le\frac{1}{\widehat{\omega}(z)}\int_{\D}
  \frac{(1-|z|)^{s}}{|1-\overline{z}u|^{s+1}}|f(u)|^q\frac{\widehat{\omega}(u)}{1-|u|}dA(u)\\
&\asymp\frac{1}{\widehat{\omega}(z)} \int_{\D}
  \frac{(1-|z|)^{s}}{|1-\overline{z}u|^{s+1}}|f(u)|^q\omega(u)dA(u)\\
&\lesssim\frac{1}{\widehat{\omega}(z)}\|f\|^q_{AT^{\infty}_q(\omega)},
\end{align*}
which proves the case $m=0$. The case $m\geq1$ then follows directly from the Cauchy integral formula. In fact, let $\Upsilon$ be the circle centered at $z$ with radius $\frac{1}{2}(1-|z|)$. Then
\begin{align*}
|f^{(m)}(z)|&\leq\frac{m!}{2\pi}\int_{\Upsilon}\frac{|f(\xi)|}{|\xi-z|^{m+1}}|d\xi|\leq\frac{2^mm!}{(1-|z|)^m}\sup_{\xi\in\Upsilon}|f(\xi)|\\
&\lesssim\frac{\|f\|_{AT^{\infty}_q(\omega)}}{(1-|z|)^m}\sup_{\xi\in\Upsilon}\frac{1}{\widehat{\omega}(\xi)^{1/q}}\leq\frac{\|f\|_{AT^{\infty}_q(\omega)}}{\widehat{\omega}\left(\frac{1+|z|}{2}\right)^{1/q}(1-|z|)^m}\\
&\lesssim\frac{\|f\|_{AT^{\infty}_q(\omega)}}{\widehat{\omega}(z)^{1/q}(1-|z|)^m}.
\end{align*}
The proof is complete.
\end{proof}

\begin{lemma}\label{test-function}
Let $0<q<\infty$, $\omega\in\DD$, and let $\gamma>\max\left\{\frac{\gamma_0(\omega)}{q},\frac{1}{q}\right\}$. Then for any $z\in\D$, the function
$$f_z(u)=\frac{1}{\widehat{\omega}(z)^{1/q}}\left(\frac{1-|z|}{1-\overline{z}u}\right)^{\gamma},\quad u\in\D$$
belongs to $AT^{\infty}_q(\omega)$, and $\|f_z\|_{AT^{\infty}_q(\omega)}\lesssim1$.
\end{lemma}
\begin{proof}
Fix $s>0$. Then for any $a\in\D$, Lemma \ref{gFR}(1) gives that
\begin{align*}
&\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}u|^{s+1}}|f_z(u)|^q\omega(u)dA(u)\\
&\ =\frac{(1-|a|)^s(1-|z|)^{q\gamma}}{\widehat{\omega}(z)}\int_{\D}\frac{\omega(u)dA(u)}{|1-\overline{a}u|^{s+1}|1-\overline{z}u|^{q\gamma}}\lesssim1.
\end{align*}
Since $a\in\D$ is arbitrary, we obtain that $f_z\in AT^{\infty}_q(\omega)$, and $\|f_z\|_{AT^{\infty}_q(\omega)}\lesssim1$.
\end{proof}

We are now ready to characterize the boundedness of $I_d:AT^{\infty}_p(\omega)\to T^{\infty}_q(\mu)$ and $I_d:AT^0_p(\omega)\to T^0_q(\mu)$. Recall that for a positive Borel measure $\mu$ on $\D$ and $r\in(0,1)$,
$$G_{\mu,r}(z)=\frac{\mu(\Delta(z,r))^{\frac{1}{q}}}{\widehat{\omega}(z)^{\frac{1}{p}}(1-|z|)^{\frac{1}{q}}}.$$

\begin{theorem}\label{bdd-em-1}
Let $0<p\leq q<\infty$, $\omega\in\DDD$, and let $\mu$ be a positive Borel measure on $\D$. Then the following conditions are equivalent:
\begin{enumerate}
    \item [(a)] $I_d:AT^{\infty}_p(\omega)\to T^{\infty}_q(\mu)$ is bounded;
    \item [(b)] $I_d:AT^0_p(\omega)\to T^0_q(\mu)$ is bounded;
    \item [(c)] for some (or any) $r\in(0,1/4)$, $G_{\mu,r}\in L^{\infty}$.
\end{enumerate}
Moreover, in these cases,
$$\|I_d\|\asymp\left\|G_{\mu,r}\right\|_{L^{\infty}}.$$
\end{theorem}
\begin{proof}
Fix $s>0$. Suppose first that (a) holds. Then, since the constant function $1$ belongs to $AT^{\infty}_{p}(\omega)$, we have
$$\|I_d\|^q\gtrsim\|1\|^q_{T^{\infty}_q(\mu)}
\gtrsim\sup_{a\in\D}\int_{\D}\frac{(1-|a|)^s}{|1-\overline{a}z|^{s+1}}d\mu(z)\geq\mu(\D),$$
which implies that for any $r\in(0,1/4)$,
$$\sup_{|z|\leq\frac{1}{2}}G_{\mu,r}(z)^q\lesssim\mu(\D)\lesssim\|I_d\|^q.$$
For any $z\in\D$ with $|z|>1/2$, write
$$\tilde{z}=\big(1-2(1-|z|)\big)\frac{z}{|z|}.$$
Then it is easy to verify that $\Delta(z,r)\subset S(\tilde{z})$ whenever $r\in(0,1/4)$. Let the function $f_z$ be defined as in Lemma \ref{test-function}. Noting that $|1-\overline{z}u|\asymp1-|z|$ for any $u\in S(\tilde{z})$, we have
\begin{align}\label{bdd-nece}
\|I_d\|^q
&\gtrsim\|f_z\|^q_{T^{\infty}_q(\mu)}\geq\frac{1}{1-|\tilde{z}|}\int_{S(\tilde{z})}|f_z(u)|^qd\mu(u)\nonumber\\
&=\frac{(1-|z|)^{q\gamma}}{\widehat{\omega}(z)^{\frac{q}{p}}(1-|\tilde{z}|)}\int_{S(\tilde{z})}\frac{d\mu(u)}{|1-\overline{z}u|^{q\gamma}}\gtrsim G_{\mu,r}(z)^q.
\end{align}

