ref_dict.remark-sharpasymp:
\begin{remark}[Rate of Convergence]\label{remark-sharpasymp}
According to the proof of Theorem~\ref{thm-2} and the proof of Lemma~\ref{lemma-convconc} in Appendix~\ref{app-convconc}, if $(\mu_t,\nu_t)$ converges to the mixed Nash equilibrium (MNE) $(\mu^*,\nu^*)$, then
\begin{equation}\label{eq-gapp}
W_2(\mu_t,\mu^*) + W_2(\nu_t,\nu^*) = O(e^{-\lambda t})
\quad \text{for all } \lambda \in (0,\lambda_{\mathrm{gap}}).
\end{equation}
Moreover, the constant $\lambda_{\mathrm{gap}}=\lambda_{gap}(f)>0$ (we call it spectral gap) can be characterized as
\[
\lambda_{\mathrm{gap}} = \min\{\lambda_{\mathrm{gap}}^{\mathcal X},\,\lambda_{\mathrm{gap}}^{\mathcal Y}\},
\]
where
\[
\lambda_{\mathrm{gap}}^{\mathcal X}
=
\inf_{\substack{\phi \in W^{2,2}(\mathcal X)\\ \nabla\phi \neq 0}}
\frac{\int \bigl(|\nabla^2\phi|^2 + \langle \nabla\phi,\nabla^2 V_{\nu^*}\nabla\phi\rangle\bigr)\,d\mu^*}
{\int |\nabla\phi|^2\,d\mu^*},
\qquad
V_{\nu^*}(x)=\int f(x,y)\,d\nu^*(y),
\]
and
\[
\lambda_{\mathrm{gap}}^{\mathcal Y}
=
\inf_{\substack{\phi \in W^{2,2}(\mathcal Y)\\ \nabla\phi \neq 0}}
\frac{\int \bigl(|\nabla^2\phi|^2 + \langle \nabla\phi,\nabla^2 U_{\mu^*}\nabla\phi\rangle\bigr)\,d\nu^*}
{\int |\nabla\phi|^2\,d\nu^*},
\qquad
U_{\mu^*}(y)=\int f(x,y)\,d\mu^*(x).
\]

\end{remark}

ref_dict.thm:main_appendix:
\begin{theorem}[Well-posedness and instantaneous smoothing]\label{thm:main_appendix}
Let $M:=\mathbb T^n$ and let $\mu_0,\nu_0\in\mathcal P(M)$ be arbitrary probability measures.
Assume $f\in C^2(M\times M)$.
Then for every $T>0$ the coupled system \eqref{eq-main}
admits a unique narrowly continuous distributional solution $(\mu_t,\nu_t)_{t\in[0,T]}$
in the sense of \eqref{eq:weak_mu2}--\eqref{eq:weak_nu2}.
Moreover, for every $\tau\in(0,T)$ there exist densities $u,v$ on $(\tau,T]\times M$ such that
$\mu_t=u(t,\cdot)\,dx$ and $\nu_t=v(t,\cdot)\,dx$ for all $t\in(\tau,T]$, and for every $p\in(1,\infty)$,
\begin{equation}\label{eq:max_reg_statement}
u,v\in L^p((\tau,T);W^{2,p}(M))\cap W^{1,p}((\tau,T);L^p(M)).
\end{equation}
\end{theorem}

ref_dict.thm:general:
\begin{theorem}\label{thm:general}
    Let $\beta$ be an algebraic number with $|\beta|=1$ which is not a root of unity. Then $\frac{\Arg(\beta)}{2\pi} \in \left(-\frac{1}{2},\frac{1}{2}\right]$ is a Diophantine number.
\end{theorem}

ref_dict.thm:3props:
\begin{theorem}\label{thm:3props}
    Let $n \ge 2$ be an integer and let $\alpha \in \left( 0, \frac{\pi}{2} \right)$ be a solution of \eqref{eq:main}. Then the following statements hold.
    \begin{enumerate}[label=(\alph*)]
        \item $\frac{\alpha}{2\pi}$ is a Diophantine number.
        \item $\frac{\alpha}{2\pi}$ is transcendental.
        \item $\alpha$ is transcendental.
    \end{enumerate}
\end{theorem}

ref_dict.thm:main:
\begin{thm}\label{thm:main}
Let $i$ be a special (cominuscule) node of the Dynkin diagram of $G,$
and $\miw{i}$ the Seidel element corresponding to $i$. Then,  for any $w\in W,$ we have 
    $$
\CO^{\miw{i}}\cdot \miw{i}^L{\CO^w}=Q^{\piv_i-w^{-1}(\piv_i)}\CO^{\miw{i} w}
$$
 in torus-equivatiant quantum $K$-theory $QK_T(G/B)$. 
\end{thm}

ref_dict.thm:Kato:
\begin{thm}[Kato \cite{Kato}, see also \cite{CL}, \cite{LLMS}]\label{thm:Kato}
There is an injective  homomorphism of $R(T)$-algebra 
$\Phi: K_*^T(\Gr_G)_\loc\rightarrow QK_T(G/B)_{\mathrm{loc}}$ such that
\begin{align}
\OGr_{t_\beta}&\mapsto Q^{\beta}\quad \text{for anti-dominant $\beta\in Q^\lor$,}\label{eq:Phi ell}
\\
\bO^w&\mapsto \CO^w\quad\text{for $w\in W$}.
\label{eq:Phi Q}
\end{align}
In particular, we have
\begin{equation}
\label{eq:Qk}
{\prod_{j\in I}\sigma_j^{-\langle \alpha_k^\lor,\alpha_j\rangle}}\mapsto Q_k\quad (k\in I).
\end{equation}
\end{thm}

expanded_sketch:
Our proof relies on the ``quantum equals affine'' philosophy, which goes
back to Peterson \cite{Pet}. A central ingredient is the $K$-theoretic Peterson isomorphism, conjectured in \cite{LLMS} and established by Kato \cite{Kato}, yielding an isomorphism of $R(T)$-algebras. We first recall the following theorem.

\begin{thm}[Kato \cite{Kato}, see also \cite{CL}, \cite{LLMS}]\label{thm:Kato}
There is an injective  homomorphism of $R(T)$-algebra 
$\Phi: K_*^T(\Gr_G)_\loc\rightarrow QK_T(G/B)_{\mathrm{loc}}$ such that
\begin{align}
\OGr_{t_\beta}&\mapsto Q^{\beta}\quad \text{for anti-dominant $\beta\in Q^\lor$,}\label{eq:Phi ell}
\\
\bO^w&\mapsto \CO^w\quad\text{for $w\in W$}.
\label{eq:Phi Q}
\end{align}
In particular, we have
\begin{equation}
\label{eq:Qk}
{\prod_{j\in I}\sigma_j^{-\langle \alpha_k^\lor,\alpha_j\rangle}}\mapsto Q_k\quad (k\in I).
\end{equation}
\end{thm}

Thus we have an isomorphism of $R(T)$-algebras
\[
\Phi:
K_*^T(\Gr_G)_{\mathrm{loc}}\xrightarrow{\ \sim\ } QK_T(G/B)_{\mathrm{loc}}.
\]
We also use an extended version of the $K$-theoretic nil-Hecke algebra developed by Ikeda--Shimozono--Yamaguchi \cite{ISY}: inside their algebra $\hat{\mathbb{K}}_{\mathrm{af}}$ they define a commutative subalgebra $\ePet$ (the extended $K$-theoretic Peterson algebra), an algebraic model for $K_*^{T^{\mathrm{ad}}}(\Gr_{G^{\mathrm{ad}}})$, equipped with a natural action of $\hat{\mathbb{K}}_{\mathrm{af}}$ incorporating the $\hat{W}_{\mathrm{af}}$-symmetry (in particular $\Sigma\simeq \pi_1(G^{\mathrm{ad}})$). The minimal facts needed for establishing the main theorem are reviewed in \S\ref{sec:ePet}, and the proof of the Seidel product formula is given in \S\ref{sec:proof}.

theorem.content:
\label{mainthm1}
  If
  \begin{equation}
    \label{eq:firstdprime}
    \mathrm{d}': \mathscr{C}^\infty(G) \longrightarrow \mathscr{C}^\infty(G; \underline{\Lambda}^{1})
    \quad \text{has closed range}
  \end{equation}
  then
  \begin{equation*}
    \mathrm{d}': \mathscr{C}^\infty(G; \underline{\Lambda}^{q - 1}) \longrightarrow \mathscr{C}^\infty(G; \underline{\Lambda}^{q})
    \quad \text{has closed range}
  \end{equation*}
  for all $1 \leq q \leq  n \doteq \rank (\mathcal{V})$. Moreover, in that case, we have
  \begin{equation}
    \label{eq:iso_scriptK}
    H^{q}_{\mathrm{d}'} (\mathscr{C}^\infty(G)) \cong \mathscr{K}(G) \otimes H^{q}_{\mathrm{d}'} (\C_G),
    \quad 0 \leq q \leq n,
  \end{equation}
  topologically, where:
  \begin{itemize}
  \item $\mathscr{K}(G)$ is the space of homogeneous solutions of $\mathcal{V}$: an $f \in \mathscr{C}^\infty(G)$ belongs to $\mathscr{K}(G)$ if and only if $\mathrm{L} f = 0$ whenever $\mathrm{L}$ is a smooth section of $\mathcal{V}$; and
  \item $H^{q}_{\mathrm{d}'} (\C_G)$ is the space of left-invariant classes\footref{f1} in $H^{q}_{\mathrm{d}'} (\mathscr{C}^\infty(G))$.
  \end{itemize}

ref_dict.thm:rep_in_K:
\begin{Thm}
  \label{thm:rep_in_K}
  If $\dd': \cinfty(G) \to \cinfty(G; \LLambda^{1})$ has closed range then
  \begin{equation*}
    H_{\dd'}^q (\bar{\RR}(G)) = 0,
    \quad \forall q \in \{0, \ldots, n\},
  \end{equation*}
  and in that case the natural map
  \begin{equation}
    \label{eq:Kintocinfty_cohom}
    H^q_{\dd'}(\K(G)) \lra H^q_{\dd'}(\cinfty(G))
  \end{equation}
  is a topological isomorphism; in particular, $H^q_{\dd'}(\cinfty(G))$ is a Fr{\'e}chet space. Moreover, every $[f] \in H^{q}_{\dd'}(\cinfty(G))$ has a representative $\pi_{\K} (f) \in \K(G; \LLambda^{q})$.
\end{Thm}

