  \item $\mathscr{K}(G)$ is the space of homogeneous solutions of $\mathcal{V}$: an $f \in \mathscr{C}^\infty(G)$ belongs to $\mathscr{K}(G)$ if and only if $\mathrm{L} f = 0$ whenever $\mathrm{L}$ is a smooth section of $\mathcal{V}$; and
  \item $H^{q}_{\mathrm{d}'} (\C_G)$ is the space of left-invariant classes\footnote{\label{f1} Here, $\C_G$ stands for the space of constant functions on $G$, and $\C_G(G; \LLambda^{q})$ for the (finite dimensional) space of left-invariant forms $u$ in $\cinfty(G; \LLambda^{q})$; i.e., those whose coefficients $u_J$ in representation~\eqref{eq:urepglobal} are all \emph{constant}.} in $H^{q}_{\mathrm{d}'} (\mathscr{C}^\infty(G))$.
  \end{itemize}

