\begin{cor}\label{cor proj}
    Let $A$ be a connected graded $\kk$-algebra, $M$ be a finitely generated graded $A$-module. Then the following are equivalent.
    \begin{enumerate}
        \item $M$ is a projective $A$-module.
        \item $\pd_A(M)\leqslant 1$, and $\Ext_A^1(M,N)=0$ for some nonzero finitely generated graded $A$-module $N$
    \end{enumerate}
\end{cor}

