\begin{equation}\label{small}
      \mm^{k}(B_{\rho}(x_0))
    \le 2k \mm(B_{\rho}(x_0)) \int_0^\rho \left( 1 - \frac{t^N}{\rho^N} \right) t^{2k - 1} \, \d t 
    \le \frac{AN}{N+2k} \omega_N \rho^{N+2k},
\end{equation}
which is exactly \eqref{equation3-13p}. On the other hand, it follows from \eqref{equation3-12} and \eqref{equation3-13} that for any $\varepsilon > 0$ there exists $\rho_\varepsilon>0$ such that
\[
(A- \varepsilon) \omega_N \rho^N \le \mm(B_{\rho}(x_0)) \le A \omega_N \rho^N, \qquad \forall \, \rho \in (0,\rho_\varepsilon].
\]
Then, for $\rho \in (0,\rho_\varepsilon]$ it follows from \eqref{ecal} that
\begin{align*}
    \mm^{k}(B_{\rho}(x_0))
    \ge 2k \int_0^\rho \bigl[(A- \varepsilon) \omega_N \rho^N - A \omega_N t^N\bigr] t^{2k - 1} \, \d t 
    = \left(\frac{AN}{N+2k} - \varepsilon \right)\omega_N \rho^{N + 2k}.
\end{align*}
Combining this with \eqref{small}, we obtain \eqref{equation3-12p}. With \eqref{equation3-12p} and \eqref{equation3-13p} in hand, using an argument similar to Step~5 in \cite{HX2024}, we can prove that $(X,\d,\mm^{k})$ is an $(N + 2k)$-volume cone. More precisely, we have
\[
\mm^{k}(B_{\rho}(x_0))=\frac{AN}{ N+2k} \omega_N \rho^{N + 2k}, \qquad \forall \rho>0.
\]
To prove that $(X,\d,\mm)$ is an $N$-volume cone, we use Fubini's theorem again:
\begin{align*}
    \mm(B_\rho(x_0))
    &=\int_{B_\rho(x_0)} \d_{x_0}^{-2k} \, \d \mm^{k} \\
    &=2k \int_{B_\rho(x_0)} \int_{\d_{x_0}(x)}^{+\infty} t^{-2k - 1} \, \d t \, \d \mm^{k} \\
    &=2k \int_0^{+\infty} \mm^{k} (B_{\min\{t,\rho\}}(x_0)) t^{-2k - 1} \, \d t \\
    &=\frac{2kAN}{N+2k} \omega_N \left( \int_0^\rho t^{N -1} \, \d t + \int_\rho^{+\infty} \rho^{N + 2k} t^{-2k -1} \, \d t \right)
    = A \omega_N \rho^N.
\end{align*}
Here, we can write \(\d \mm=\d_{x_0}^{-2k}\,\d \mm^k\) since \(\mm\) is non-atomic (due to MCP spaces) and thus $\mm(\{x_0\}) = 0$. Thus, $(X,\d, \mm)$ is an $N$-volume cone, and this completes the proof of Theorem \ref{Theorem2}.
\end{proof}

\subsection{Proof of Proposition \ref{stability}}\label{3.4}

\begin{proof}
We still use the needle decomposition method as in the proof of Theorem \ref{Theorem2}, and we obtain
\begin{equation*}
\mm=\int_Q \mm_\alpha\, \d\mathfrak{q}(\alpha),\qquad (X_\alpha,\d,\mm_\alpha)\cong ([0, +\infty),|\cdot|,c_{\alpha}x^{N-1}\mathrm{d}x),
\end{equation*}
where, for $\mathfrak{q}$-a.e.\ $\alpha \in Q$, $X_\alpha$ has $x_0$ as an extremal point.

Fix $u:=u_0(\d_{x_0})\in S^r_{x_0}$. Now, using \cite[Theorem 1.8]{LLR2026} (see also its proof), we know that
\begin{align*}
    &\left( \int_0^{+\infty} |u_0'|^2(x) x^{N + 2k - 1} \, \d x \right)^{\frac{1}{2}}\left( \int_0^{+\infty} |u_0|^2(x) x^{N + 2k + 1} \, \d x \right)^{\frac{1}{2}}
     \\
    &\quad - \left(\frac{N }{2} + k\right) \int_0^{+\infty} |u_0|^2(x) x^{N + 2k - 1} \, \d x
    \ge  \int_0^{+\infty} \left|u_0(x) - \eta \, e^{-\frac{x^2}{2\xi^2}} \right|^2 x^{N + 2k - 1} \, \d x,
\end{align*}
where
\begin{align*}
    \xi &:=  \xi(u_0) = \left( \frac{\int_0^{+\infty} |u_0|^2(x) x^{N + 2k + 1} \, \d x}{\int_0^{+\infty} |u_0'|^2(x) x^{N + 2k - 1} \, \d x} \right)^{\frac{1}{4}}, \\
    \eta &:=  \eta(u_0) = \frac{\int_0^{+\infty} u_0(x) x^{N + 2k - 1} e^{-\frac{x^2}{2\xi^2}}  \, \d x}{\int_0^{+\infty} x^{N + 2k - 1} e^{-\frac{x^2}{\xi^2}}  \, \d x},
\end{align*}
which are two constants independent of $\alpha$. Multiplying both sides by $c_\alpha$ and rewriting the inequality on $X_\alpha$ yield that for $\mathfrak{q}$-a.e.\ $\alpha \in Q$,
\begin{align*}
    &\left( \int_{X_\alpha} |u_0'|^2(\d_0) \d_0^{2k } \, \d \mm_\alpha \right)^{\frac{1}{2}}\left( \int_{X_\alpha} |u_0|^2(\d_0) \d_0^{2k + 2} \, \d \mm_\alpha \right)^{\frac{1}{2}}\\
    &\quad - \left(\frac{N }{2} + k\right) \int_{X_\alpha} |u_0|^2(\d_0) \d_0^{2k } \, \d \mm_\alpha
    \ge  \int_{X_\alpha} \left|u_0(\d_0) - \eta \, e^{-\frac{\d_0^2}{2\xi^2}} \right|^2 \d_0^{2k } \, \d \mm_\alpha.
\end{align*}
 Finally, integrating with respect to $\alpha$, applying the Cauchy--Schwarz inequality, and using the fact that $|u_0'|(\d_{x_0}) \le |\mathrm{lip}\, u|$, we obtain 
\begin{align*}
 &\left( \int_{X} |\mathrm{lip}\, u|^2 \d_{x_0}^{2k } \, \d \mm \right)^{\frac{1}{2}}\left( \int_{X} |u|^2 \d_{x_0}^{2k + 2} \, \d \mm \right)^{\frac{1}{2}}
    - \left(\frac{N }{2} + k\right) \int_{X} |u|^2 \d_{x_0}^{2k } \, \d \mm\\
    \geq&\left( \int_{X} |u_0'|^2(\d_{x_0}) \d_{x_0}^{2k } \, \d \mm \right)^{\frac{1}{2}}\left( \int_{X} |u_0|^2(\d_{x_0}) \d_{x_0}^{2k + 2} \, \d \mm \right)^{\frac{1}{2}}
    - \left(\frac{N }{2} + k\right) \int_{X} |u_0|^2(\d_{x_0}) \d_{x_0}^{2k } \, \d \mm\\
    \ge&  \int_{X} \left|u_0(\d_{x_0}) - \eta \, e^{-\frac{\d_{x_0}^2}{2\xi^2}} \right|^2 \d_{x_0}^{2k } \, \d \mm \geq\inf_{v \in E_{G,x_0}} \left\{ \int_X |u - v|^2 \d_{x_0}^{2k} \, \d \mm \right\}.
\end{align*}
So we finish the proof of Proposition \ref{stability}.
\end{proof}

\subsection{Counterexample}\label{3.5}
\begin{example}
Let $n\ge 1$. Set
\[
X=\mathbb R^n,\qquad \d(x,y)=|x-y|,\qquad x_0=0 \qquad (\mathrm{i.e.} \,\,\d_0(x) = |x|)
\]
and define a Radon measure on $X$ by
\[
\mm := \mathcal L^n + M\delta_{0},\qquad M>0,
\]
where $\mathcal L^n$ denotes the $n$-dimensional Lebesgue measure and $\delta_0$ the Dirac mass at $0$.
Then, for the choice of the constant $C = \frac{n}{2}$, \ref{first} holds for any $k\ge 1$ and any $u\in \mathrm{Lip}_b(X,\d)$, but it fails for $k=0$.
Moreover, the function $\rho \mapsto \frac{\mm(B_\rho(x_0))}{\rho^{2C}}$ cannot be non-decreasing on $(0,+\infty)$.
\end{example}

\begin{proof}
It is not hard to see that $(X,\d)$ is Polish, and $0<\mm(U)<+\infty$ for every non-empty bounded open set $U\subset\mathbb R^n$.
First, for every $\lambda>0$,
\[
\int_X e^{-2\lambda \d^2_0}\,\d \mm
= \int_{\mathbb R^n} e^{-2\lambda |x|^2}\,\d x + M <+\infty.
\]

Next, we check that \ref{first} holds for any $k\ge 1$ with $C=\frac n2$ and $x_0=0$.
Recall that $(\mathrm{CKN})_{C,0,k}$ reads: for any $u\in {\rm Lip}_b(X,\d)$,
\begin{equation}\label{eq:CKN}
\Big(\int_X \d_{0}^{2k}\,|{\rm lip}\,u|^2\,\d\mm\Big)
\Big(\int_X \d_{0}^{2k+2}\,|u|^2\,\d\mm\Big)
\ge (C+k)^2\Big(\int_X \d_{0}^{2k}\,|u|^2\,\d\mm\Big)^2.
\end{equation}

post_theorem_intro_text:
The motivation is as follows. The extremisers of \eqref{Euclidean} are precisely Gaussian functions. Roughly speaking, if we test \ref{first} with functions in the Gaussian class
\begin{equation}\label{Gauss}
    E_{G,x_0} := \{c e^{-\lambda \d_{x_0}^2} : \, c \in \mathbb R, \lambda > 0\},
\end{equation}
then, by the layer cake representation (or Fubini's theorem) together with a change of variables, we find that the Laplace transform of a certain function related to the volume of metric balls is non-negative. However, this does not directly imply that the function itself is non-negative. To obtain such a conclusion, we need to use Bernstein's theorem, whose assumptions are exactly \ref{first} for every $k\in \mathbb N$ with a $k$-independent constant $C>0$. For more details, we refer the reader to the proof of Theorem \ref{Theorem1}.

\begin{remark}\label{con}
It turns out that, in order to obtain the conclusion of Theorem \ref{Theorem1}, we genuinely need \ref{first} to hold for all $k\in \mathbb N$. In fact, in Subsection \ref{3.5} we shall present a counterexample for which \ref{first} holds for all $k\ge 1$ with a $k$-independent constant $C>0$ but fails for $k=0$; in this case, the function $\rho \longmapsto \mathfrak m(B_\rho(x_0))/\rho^{2C}$
is not non-decreasing.
\end{remark}

\begin{corollary}\label{prop1}
Let $\beta,\gamma>0$, $D\geq 1$, and $(X,\mathrm{d},\mathfrak m)$ be a metric measure space, and fix $x_0 \in X$. Assume that there exists a constant $C>0$, independent of $k$, such that for any $k \in \mathbb N$ and any $u\in \mathrm{Lip}_b(X,\mathrm{d})$ the inequality \ref{first} holds. Suppose also that
\begin{align}
\label{VD}\tag*{$(\mathrm{VD})_{D,\gamma}$}
\frac{\mathfrak m(B_{R}(x))}{R^\gamma} &\le D\,\frac{\mathfrak m(B_{r}(x))}{r^\gamma}, \qquad \forall \, 0<r<R,\, x \in X, \\
\label{AR}\tag*{$(\mathrm{AR})_{x_0, \beta, c_*}$}
\liminf_{r \to 0^+} &\frac{\mathfrak m(B_{r}(x_0))}{r^\beta} = c_* \in (0,+\infty).
\end{align}
Then $2C \le \beta \le \gamma$, and there exists a constant $C_*>0$ such that
\begin{align}\label{loweruni}
\frac{\mathfrak m(B_{r}(x))}{r^\beta}
\ge C_* \frac{1}{(1 + r + \mathrm{d}(x_0,x))^{\beta - 2C}}
\cdot\frac{1}{\left( 1 + \frac{\mathrm{d}(x_0,x)}{r}\right)^{\gamma - \beta}},
\qquad \forall \, r > 0,\, x \in X.
\end{align}
\end{corollary}

Next, we extend the rigidity result in \cite{HX2024} to $L^2$-CKN.
\begin{theorem}\label{Theorem2}
Let $N\in(1,{+\infty})$. Let $(X,\mathrm{d},\mathfrak m)$ be an essentially non-branching metric measure space satisfying ${\rm MCP}(0,N)$. Then the following statements are equivalent:
\begin{itemize}
\item[{\bf (a)}] There exist $x_0\in X$ and $k\in\mathbb{N}$ such that \ref{first} holds with the sharp constant $C=\frac{N}{2}$;
\item[{\bf (b)}] There exists $x_0\in X$ such that, for every $k\in\mathbb{N}$, \ref{first} holds with the sharp constant $C=\frac{N}{2}$;
\item[{\bf (c)}] $(X,\mathrm{d},\mathfrak m)$ is an $N$-volume cone.
\end{itemize}
\end{theorem}
In Theorem~\ref{Theorem2}, sharpness is understood in the sense that the sharp constant in \ref{first2} on $(X,\mathrm{d},\mathfrak m)$ is $\left(\frac{N}{2}+k\right)^2$, as in the Euclidean space $\mathbb{R}^N$.

\medskip

Finally, motivated by the recent paper \cite{LLR2026}, we investigate the stability of \ref{first} on general metric measure spaces.

\begin{proposition}\label{stability}
Let $N\in(1,{+\infty})$ and $k \in \mathbb N$. Let $(X,\mathrm{d},\mathfrak m)$ be an essentially non-branching metric measure space satisfying ${\rm MCP}(0,N)$, and assume that it is also an $N$-volume cone with vertex $x_0 \in X$. Then
\[
\delta_{k}(u) \ge \mathbb{D}_k^2(u,E_{G,x_0}), \qquad \forall \, u \in S_{x_0}^{r}.
\]
Here,
\[
\delta_{k}(u) := \left( \int_X \d_{x_0}^{2k}\,|\mathrm{lip}\, u|^{2}\, \mathrm{d}\mathfrak m \right)^{\frac{1}{2}}
\left( \int_X \d_{x_0}^{2k+2}\,|u|^{2}\, \mathrm{d}\mathfrak m \right)^{\frac{1}{2}}
- \left(\frac{N}{2}+k\right)
 \int_X \d_{x_0}^{2k}\,|u|^{2}\, \mathrm{d}\mathfrak m
\]
is the deficit, and
\[
\mathbb{D}_k^2(u,E_{G,x_0}) := \inf_{v \in E_{G,x_0}} \left\{ \int_X |u - v|^2 \d_{x_0}^{2k} \, \mathrm{d} \mathfrak m \right\},\quad
S_{x_0}^{r} := \{ u_0(\d_{x_0}) : u_0 \in C_0^\infty((0,+\infty)) \}.
\]
Moreover, $E_{G,x_0}$ is defined by \eqref{Gauss}.
\end{proposition}

For further stability results concerning other versions of the CKN inequalities, we refer the reader to \cite{CFLL2024,FP2024,WW2022,ZZ2026}.

\subsection{Some Generalisations}
In fact, our argument also applies to the $L^p$ analogues.
\begin{theorem}\label{Theorem1p}
Let $(X,\mathrm{d},\mathfrak m)$ be a metric measure space and $p \in (1,+\infty)$. Fix $x_0 \in X$, and denote the conjugate exponent of $p$ by $p' := \frac{p}{p - 1}$.
Assume that, for any $\lambda > 0$,
\[
\int_X e^{-p \lambda \d_{x_0}^{p'}} \, \mathrm{d}\mathfrak m < {+\infty},
\]
and that there exists a constant $C>0$, independent of $k$, such that for any $k \in \mathbb N$ and any $u\in \mathrm{Lip}_b(X,\mathrm{d})$ the following inequality holds:
\begin{equation}\label{firstp}
\left( \int_X \d_{x_0}^{p'k}\,|\mathrm{lip}\, u|^{p}\, \mathrm{d}\mathfrak m \right)
\left( \int_X \d_{x_0}^{p'(k + 1)}\,|u|^{p}\, \mathrm{d}\mathfrak m \right)^{p - 1}
\geq \left( \frac{ C + k}{p - 1}\right)^p
\left( \int_X \d_{x_0}^{p'k}\,|u|^{p}\, \mathrm{d}\mathfrak m \right)^{p}.
\end{equation}
Then, for any $\ell \in \mathbb N$, the function
\[
\rho \longmapsto \frac{\mathfrak m^{\ell,p}(B_\rho(x_0))}{\rho^{p'(C +\ell)}}
\]
is non-decreasing on $(0,{+\infty})$. Here the measure $\mathfrak m^{\ell,p}$ is defined by $\mathrm{d} \mathfrak m^{\ell,p} = \d_{x_0}^{p'\ell} \mathrm{d} \mathfrak m$.
\end{theorem}

\begin{remark}
We choose to write the constant in \eqref{firstp} as $\left( \frac{ C + k}{p - 1}\right)^p$ rather than $\left(  C+ \frac{k}{p - 1}\right)^p$ in order to make the proof more compatible with the proof of Theorem \ref{Theorem1}.
\end{remark}

Furthermore, for $p \in (1, +\infty)$ we can also obtain the analogues of Corollary \ref{prop1} (replacing $2$ by $p'$) and Theorem \ref{Theorem2} (with sharp constant $\frac{N}{p'}$), but we omit the statements here.

\subsection{Structure of the paper}
In Section \ref{section2} we recall the Bernstein's theorem and basic properties of the measure contraction property. In Section \ref{3.1} we prove Theorem \ref{Theorem1} by using the Bernstein's theorem. In Section \ref{3.2} we prove Corollary \ref{prop1}. In Section \ref{3.3} we prove Theorem \ref{Theorem2} by using the needle decomposition of measures. In Section \ref{3.4} we establish the stability result in Proposition \ref{stability}. Finally, in Section \ref{3.5} we provide the counterexample mentioned in Remark \ref{con}.

