sketch:
Since Theorem \ref{t:char-hke} follows readily from Theorem \ref{t:main} together with known results, we only outline the proof of Theorem \ref{t:main}. The Whitney blending argument proceeds in three main steps:
\begin{enumerate}
\item "We establish a cutoff Sobolev-type inequality" when "the cutoff function is chosen as the equilibrium potential for $K \subset \Omega$, for functions that vanish either in a neighborhood of $K$ or in a neighborhood of $\Omega^c$" (Lemma \ref{l:zerobdy-cs}).
\item Given $f\in\mathcal{F}$, $x_0\in X$, $r>0$, construct $f_1,f_2\in\mathcal{F}$ with $|f|\le |f_1|+|f_2|$, where " $f_1$ vanishes in a neighborhood of $\overline{B(x_0,r)}$" and " $f_2$ vanishes in a neighborhood of $B(x_0,2r)^c$". Apply the previous cutoff Sobolev-type inequality to $f_1,f_2$ to get "a cutoff Sobolev inequality for the equilibrium potential associated with $\overline{B(x_0,r)}\subset B(x_0,2r)$". The key difficulty is "controlling the energies of $f_1$ and $f_2$ in terms of the energy of $f$", handled using "Whitney covers" (Lemma \ref{l:wb}); the construction also uses "the explicit description of the domain of the Dirichlet form" (Proposition \ref{p:domain}).
\item The previous step yields "a non-local analogue of the simplified cutoff Sobolev inequality" (Proposition \ref{p:css}). Then "a self-improvement argument, following \cite[Proof of Lemma~6.2]{Mur24}, then yields the desired cutoff Sobolev inequality" (\textsection \ref{ss:self-improve}).
\end{enumerate}

expanded_sketch:
Since \begin{theorem} \label{t:char-hke}
	Let $(X,d,m)$ be a metric measure space  that satisfies 	\hyperlink{vd}{$\on{VD}$} and \hyperlink{qrvd}{$\on{QRVD}$}. Let $(\mathcal{E},\mathcal{F})$ be a pure jump Dirichlet form on $L^2(X,m)$. Then the following are equivalent:
	\begin{enumerate}[(a)]
		\item Jump kernel bound  \hyperlink{jphi}{$\on{J(\phi)}$}, and capacity upper bound \hyperlink{cap}{$\on{Cap(\phi)_{\le}}$}.
		\item Stable-like heat kernel bound \hyperlink{shk}{$\on{HK}(\phi)$}.
	\end{enumerate}
\end{theorem}
 follows readily from the main theorem together with known results, we only outline the proof of the main theorem. The Whitney blending argument proceeds in three main steps:
\begin{enumerate}
\item We establish a cutoff Sobolev-type inequality when the cutoff function is chosen as the equilibrium potential for $K \subset \Omega$, for functions that vanish either in a neighborhood of $K$ or in a neighborhood of $\Omega^c$. We first prove the following lemma.

\begin{lemma} \label{l:zerobdy-cs}
			Let $(\mathcal{E},\mathcal{F})$ be a regular, pure jump Dirichlet form on $L^2(X,m)$ with jump measure $J(dx,dy)= J(x,y)\,m(dx)\,m(dy)$. 
	Let $\psi$ be the equilibrium potential for $K \subset \Omega$, where $\Omega$ is a non-polar, precompact open subset and $K$ is compact. Let $f \in \mathcal{F} \cap C(X)$ be   one of the following conditions hold:
	\begin{enumerate}[(a)]
		\item $f \equiv 0$ on some neighborhood of $\Omega^c$, or
		\item $f \equiv 0$ on some neighborhood of $K$.
	\end{enumerate}
	Then for any $U \subset X$, 
	\begin{equation} \label{e:zero-bdy}
	\int_{U} f^2\,d\Gamma(\psi,\psi) \le 48 \Gamma(f,f)(U).
	\end{equation}
\end{lemma}

\item Given $f\in\mathcal{F}$, $x_0\in X$, $r>0$, construct $f_1,f_2\in\mathcal{F}$ with $|f|\le |f_1|+|f_2|$, where $f_1$ vanishes in a neighborhood of $\overline{B(x_0,r)}$ and $f_2$ vanishes in a neighborhood of $B(x_0,2r)^c$. Apply the preceding lemma to $f_1,f_2$ to get a cutoff Sobolev inequality for the equilibrium potential associated with $\overline{B(x_0,r)}\subset B(x_0,2r)$. The key difficulty is controlling the energies of $f_1$ and $f_2$ in terms of the energy of $f$, handled using Whitney covers via the following lemma:

\begin{lem} \label{l:wb}
	For any $\eta \in (0,1)$, there exists $C$ depending only on the constants in \hyperlink{jphi}{$\on{J(\phi)}$},  \hyperlink{vd}{$\on{VD}$}, and   $\eta$  such that, for any $x_0 \in X, 0<r <\diam(X,d)/4$ and for any $f,g \in \mathcal{F} \cap C(X)$ and for any $A \in [2,\infty)$, there exists $h \in \mathcal{F} \cap C(X)$ such that  $h \equiv f$ on $B(x_0,r)$, $h \equiv g$ on $B(x_0,(1+\eta)r)^c$ and 
	\begin{align} \label{e:wb}
	\MoveEqLeft{\int_{B(x_0,Ar) \times B(x_0,Ar)}(h(x)-h(y))^2) \,J(dx,dy)} \\ &\le C \int_{B(x_0,Ar) \times B(x_0,Ar)}((f(x)-f(y))^2+(g(x)-g(y))^2) \,J(dx,dy)   		    + \frac{C}{\phi(r)} \int_{B(x_0,Ar)} (f-g)^2\,dm. \nonumber
	\end{align}
\end{lem}

The construction also uses the explicit description of the domain of the Dirichlet form given by the following proposition: 

\begin{prop} \label{p:domain} 	Let $(X,d,m)$ be a metric measure space  that satisfies 	\hyperlink{vd}{$\on{VD}$}. Let $(\mathcal{E},\mathcal{F})$ be a pure jump Dirichlet form that satisfies 
	\hyperlink{jphi}{$\on{J(\phi)}$}, and \hyperlink{cap}{$\on{Cap(\phi)_{\le}}$}. Then we have $\mathcal{F} = \wh{\mathcal{F}}$.
\end{prop}

\item The previous step yields a non-local analogue of the simplified cutoff Sobolev inequality, namely the following proposition.

\begin{prop} \label{p:css}
Let $(\mathcal{E},\mathcal{F})$ be a regular, pure jump Dirichlet form on $L^2(X,m)$ that satisfies  \hyperlink{jphi}{$\operatorname{J(\phi)}$} and   \hyperlink{cap}{$\operatorname{Cap(\phi)_{\le}}$}, where $\phi:[0,\infty) \to [0,\infty)$ is a scale function. Then there exists $C>0$ such that for any $r,\rho>0, f\in C(X) \cap \mathcal{F}$, the equilibrium potential $\psi$ for $\overline{B(x,r)} \subset B(x,2r)$ for the truncated Dirichlet form $(\mathcal{E}^{(\rho)}, \mathcal{F})$ satisfies
\begin{align} \label{e:css}
	\int_X f^2 \,d\Gamma^{(\rho)}(\psi,\psi) &= \int_{B(x,2r+\rho)} f^2 \,d\Gamma^{(\rho)}(\psi,\psi) \nonumber\\
	& \le C  	\int_{B(x,2r+2\rho)} \int_{B(x,2r+2\rho)} (f(y)-f(z))^2  J(y,z)\,m(dy)\,m(dz) \nonumber \\
	&\quad\quad\quad+ \frac{C}{\phi(r)} \int_{B(x,2r)} f^2\,dm 
\end{align}
\end{prop}

Then a self-improvement argument, following \cite[Proof of Lemma~6.2]{Mur24}, yields the desired cutoff Sobolev inequality.
\end{enumerate}

